--
-- Name: _pp_run_processors(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._pp_run_processors(p_uid uuid, p_staffed_ids uuid[]) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_now timestamptz := now();
  v_total numeric := 0;
  v_b record;
  v_elapsed numeric;
BEGIN
  FOR v_b IN
    SELECT b.id, b.last_processed_at,
           bt.input_resource_key, bt.input_rate,
           bt.input_resource_key_2, bt.input_rate_2,
           bt.output_resource_key, bt.output_rate
    FROM public.buildings b
    JOIN public.building_types bt ON bt.key = b.building_type_key
    WHERE b.player_id = p_uid AND b.status = 'active' AND bt.category = 'processor'
      AND b.id = ANY(p_staffed_ids)
    FOR UPDATE OF b
  LOOP
    v_elapsed := EXTRACT(EPOCH FROM (v_now - v_b.last_processed_at));
    DECLARE
      v_need1 numeric := COALESCE((v_elapsed / 60.0) * v_b.input_rate,   0);
      v_need2 numeric := COALESCE((v_elapsed / 60.0) * v_b.input_rate_2, 0);
      v_avail1 numeric := 0;
      v_avail2 numeric := 0;
      v_used1 numeric := 0;
      v_used2 numeric := 0;
      v_progress numeric := 1;
      v_made numeric := 0;
    BEGIN
      IF v_b.input_resource_key IS NOT NULL THEN
        SELECT COALESCE(quantity, 0) INTO v_avail1 FROM public.inventories
        WHERE player_id = p_uid AND resource_key = v_b.input_resource_key;
      END IF;
      IF v_b.input_resource_key_2 IS NOT NULL THEN
        SELECT COALESCE(quantity, 0) INTO v_avail2 FROM public.inventories
        WHERE player_id = p_uid AND resource_key = v_b.input_resource_key_2;
      END IF;
      IF v_need1 > 0 THEN v_progress := LEAST(v_progress, v_avail1 / v_need1); END IF;
      IF v_need2 > 0 THEN v_progress := LEAST(v_progress, v_avail2 / v_need2); END IF;
      v_progress := GREATEST(0, v_progress);
      IF v_progress > 0 THEN
        IF v_need1 > 0 AND v_b.input_resource_key IS NOT NULL THEN
          v_used1 := v_need1 * v_progress;
          UPDATE public.inventories SET quantity = quantity - v_used1
          WHERE player_id = p_uid AND resource_key = v_b.input_resource_key;
        END IF;
        IF v_need2 > 0 AND v_b.input_resource_key_2 IS NOT NULL THEN
          v_used2 := v_need2 * v_progress;
          UPDATE public.inventories SET quantity = quantity - v_used2
          WHERE player_id = p_uid AND resource_key = v_b.input_resource_key_2;
        END IF;
        v_made := (v_elapsed / 60.0) * v_b.output_rate * v_progress;
        IF v_made > 0 AND v_b.output_resource_key IS NOT NULL THEN
          INSERT INTO public.inventories (player_id, resource_key, quantity)
          VALUES (p_uid, v_b.output_resource_key, v_made)
          ON CONFLICT (player_id, resource_key)
          DO UPDATE SET quantity = public.inventories.quantity + EXCLUDED.quantity;
          v_total := v_total + v_made;
        END IF;
      END IF;
      UPDATE public.buildings SET last_processed_at = v_now WHERE id = v_b.id;
    END;
  END LOOP;
  RETURN v_total;
END;
$$;


--
-- Name: _pp_run_services(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._pp_run_services(p_uid uuid, p_staffed_ids uuid[]) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_now timestamptz := now();
  v_op uuid[] := ARRAY[]::uuid[];
  v_b record;
  v_elapsed numeric;
BEGIN
  FOR v_b IN
    SELECT b.id, b.last_processed_at, b.building_type_key,
           bt.input_resource_key, bt.input_rate,
           bt.input_resource_key_2, bt.input_rate_2,
           bt.output_rate
    FROM public.buildings b
    JOIN public.building_types bt ON bt.key = b.building_type_key
    WHERE b.player_id = p_uid AND b.status = 'active' AND bt.category = 'service'
      AND b.id = ANY(p_staffed_ids)
    FOR UPDATE OF b
  LOOP
    v_elapsed := EXTRACT(EPOCH FROM (v_now - v_b.last_processed_at));
    DECLARE
      v_need1 numeric := COALESCE((v_elapsed / 60.0) * v_b.input_rate,   0);
      v_need2 numeric := COALESCE((v_elapsed / 60.0) * v_b.input_rate_2, 0);
      v_avail1 numeric := 0;
      v_avail2 numeric := 0;
      v_operating boolean;
    BEGIN
      IF v_b.input_resource_key IS NOT NULL THEN
        SELECT COALESCE(quantity, 0) INTO v_avail1 FROM public.inventories
        WHERE player_id = p_uid AND resource_key = v_b.input_resource_key;
      END IF;
      IF v_b.input_resource_key_2 IS NOT NULL THEN
        SELECT COALESCE(quantity, 0) INTO v_avail2 FROM public.inventories
        WHERE player_id = p_uid AND resource_key = v_b.input_resource_key_2;
      END IF;
      v_operating :=
        (v_b.input_resource_key   IS NULL OR v_avail1 >= v_need1)
        AND (v_b.input_resource_key_2 IS NULL OR v_avail2 >= v_need2);
      IF v_operating THEN
        IF v_need1 > 0 AND v_b.input_resource_key IS NOT NULL THEN
          UPDATE public.inventories SET quantity = quantity - v_need1
          WHERE player_id = p_uid AND resource_key = v_b.input_resource_key;
        END IF;
        IF v_need2 > 0 AND v_b.input_resource_key_2 IS NOT NULL THEN
          UPDATE public.inventories SET quantity = quantity - v_need2
          WHERE player_id = p_uid AND resource_key = v_b.input_resource_key_2;
        END IF;
        v_op := v_op || v_b.id;
      END IF;
      UPDATE public.buildings SET last_processed_at = v_now WHERE id = v_b.id;
    END;
  END LOOP;
  RETURN v_op;
END;
$$;


--
-- Name: _pp_run_tax(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._pp_run_tax(p_uid uuid, p_staffed_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_now timestamptz := now();
  v_total integer := 0;
  v_b record;
  v_elapsed numeric;
  v_amt numeric;
BEGIN
  FOR v_b IN
    SELECT b.id, b.last_processed_at, bt.output_rate
    FROM public.buildings b
    JOIN public.building_types bt ON bt.key = b.building_type_key
    WHERE b.player_id = p_uid AND b.status = 'active' AND bt.category = 'tax'
      AND b.id = ANY(p_staffed_ids)
    FOR UPDATE OF b
  LOOP
    v_elapsed := EXTRACT(EPOCH FROM (v_now - v_b.last_processed_at));
    v_amt := FLOOR((v_elapsed / 60.0) * v_b.output_rate);
    IF v_amt > 0 THEN
      UPDATE public.player_profiles SET money = money + v_amt::integer WHERE id = p_uid;
      v_total := v_total + v_amt::integer;
    END IF;
    UPDATE public.buildings SET last_processed_at = v_now WHERE id = v_b.id;
  END LOOP;

  IF v_total > 0 THEN
    INSERT INTO public.cash_transactions (player_id, source, amount, context)
    VALUES (p_uid, 'tax_revenue', v_total, NULL);
  END IF;

  RETURN v_total;
END;
$$;


--
-- Name: _pp_run_upkeep(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._pp_run_upkeep(p_uid uuid, p_staffed_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_now timestamptz := now();
  v_total integer := 0;
  v_b record;
  v_elapsed numeric;
  v_amt numeric;
BEGIN
  FOR v_b IN
    SELECT b.id, b.last_processed_at, bt.upkeep_per_minute
    FROM public.buildings b
    JOIN public.building_types bt ON bt.key = b.building_type_key
    WHERE b.player_id = p_uid AND b.status = 'active'
      AND bt.upkeep_per_minute > 0
      AND b.id = ANY(p_staffed_ids)
    FOR UPDATE OF b
  LOOP
    v_elapsed := EXTRACT(EPOCH FROM (v_now - v_b.last_processed_at));
    v_amt := FLOOR((v_elapsed / 60.0) * v_b.upkeep_per_minute);
    IF v_amt > 0 THEN
      UPDATE public.player_profiles SET money = money - v_amt::integer WHERE id = p_uid;
      v_total := v_total + v_amt::integer;
    END IF;
    UPDATE public.buildings SET last_processed_at = v_now WHERE id = v_b.id;
  END LOOP;

  IF v_total > 0 THEN
    INSERT INTO public.cash_transactions (player_id, source, amount, context)
    VALUES (p_uid, 'upkeep', -v_total, NULL);
  END IF;

  RETURN v_total;
END;
$$;


--
-- Name: _pp_staff_buildings(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._pp_staff_buildings(p_uid uuid, p_supply integer, OUT staffed_ids uuid[], OUT workers_needed integer, OUT unstaffed_count integer) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_remaining integer := p_supply;
  v_b record;
BEGIN
  staffed_ids := ARRAY[]::uuid[];
  workers_needed := 0;
  unstaffed_count := 0;

  -- Reset is_staffed for ALL of this player's worker-pool candidates
  -- (whether or not they get workers this tick).
  UPDATE public.buildings b
  SET is_staffed = false
  FROM public.building_types bt
  WHERE bt.key = b.building_type_key
    AND b.player_id = p_uid AND b.status = 'active'
    AND bt.category IN ('extractor','food_extractor','booster','processor','tax','service','police');

  FOR v_b IN
    SELECT b.id, bt.worker_cost
    FROM public.buildings b
    JOIN public.building_types bt ON bt.key = b.building_type_key
    WHERE b.player_id = p_uid AND b.status = 'active'
      AND bt.category IN ('extractor','food_extractor','booster','processor','tax','service','police')
      AND public.has_road_access(p_uid, b.x, b.y)
    ORDER BY b.staffing_priority DESC, b.created_at ASC
  LOOP
    workers_needed := workers_needed + v_b.worker_cost;
    IF v_remaining >= v_b.worker_cost THEN
      staffed_ids := staffed_ids || v_b.id;
      v_remaining := v_remaining - v_b.worker_cost;
      UPDATE public.buildings SET is_staffed = true WHERE id = v_b.id;
    ELSE
      unstaffed_count := unstaffed_count + 1;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: _pp_tavern_bonus(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._pp_tavern_bonus(p_uid uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_now timestamptz := now();
  v_tavern integer := 0;
BEGIN
  SELECT COALESCE(SUM(bt.output_rate), 0)::integer INTO v_tavern
  FROM public.buildings b
  JOIN public.building_types bt ON bt.key = b.building_type_key
  WHERE b.player_id = p_uid AND b.status = 'active' AND bt.key = 'tavern'
    AND public.has_road_access(p_uid, b.x, b.y)
    AND COALESCE(
          (SELECT i.quantity FROM public.inventories i
            WHERE i.player_id = p_uid AND i.resource_key = bt.input_resource_key), 0)
        >= ((EXTRACT(EPOCH FROM (v_now - b.last_processed_at)) / 60.0) * bt.input_rate)
    AND COALESCE(
          (SELECT i.quantity FROM public.inventories i
            WHERE i.player_id = p_uid AND i.resource_key = bt.input_resource_key_2), 0)
        >= ((EXTRACT(EPOCH FROM (v_now - b.last_processed_at)) / 60.0) * bt.input_rate_2);
  RETURN v_tavern;
END;
$$;


--
-- Name: _pp_update_crime(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._pp_update_crime(p_uid uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_crime numeric;
BEGIN
  v_crime := public.compute_crime(p_uid);
  UPDATE public.player_profiles SET crime = v_crime WHERE id = p_uid;
  RETURN v_crime;
END;
$$;


--
-- Name: _pp_update_population(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._pp_update_population(p_uid uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_target numeric;
  v_pop numeric;
  v_happiness numeric;
  v_last timestamptz;
  v_minutes numeric;
  v_max_rate constant numeric := 1.0;
  v_delta numeric;
BEGIN
  v_target := 5 + public._pp_housing_supply(p_uid);

  SELECT population, last_population_tick_at INTO v_pop, v_last
  FROM public.player_profiles WHERE id = p_uid;
  IF v_pop IS NULL THEN v_pop := 5; END IF;
  IF v_last IS NULL THEN v_last := now() - interval '1 minute'; END IF;

  v_minutes := GREATEST(0, EXTRACT(EPOCH FROM (now() - v_last)) / 60.0);
  IF v_minutes > 60 THEN v_minutes := 60; END IF;

  v_happiness := (public.compute_happiness(p_uid)->>'happiness')::numeric;

  IF v_target > v_pop THEN
    -- Empty homes fill instantly with new arrivals.
    v_pop := v_target;
  ELSIF v_happiness < 50 THEN
    -- At/above target but unhappy → citizens slowly leave.
    v_delta := ((50 - v_happiness) / 50.0) * v_max_rate * v_minutes;
    v_pop := GREATEST(0, LEAST(v_target, v_pop - v_delta));
  ELSE
    -- At/above target and content → clamp down to target if housing was lost.
    v_pop := LEAST(v_target, v_pop);
  END IF;

  UPDATE public.player_profiles
  SET population = v_pop,
      happiness = v_happiness,
      last_population_tick_at = now()
  WHERE id = p_uid;

  RETURN v_pop;
END;
$$;


--
-- Name: _pp_workers_needed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._pp_workers_needed(p_uid uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_total integer;
BEGIN
  SELECT COALESCE(SUM(bt.worker_cost), 0) INTO v_total
  FROM public.buildings b
  JOIN public.building_types bt ON bt.key = b.building_type_key
  WHERE b.player_id = p_uid AND b.status = 'active'
    AND bt.category IN ('extractor','food_extractor','booster','processor','tax','service','police')
    AND public.has_road_access(p_uid, b.x, b.y);
  RETURN v_total;
END;
$$;


--
-- Name: _rtv_buy_phase(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._rtv_buy_phase(p_uid uuid, p_trader_key text, p_capacity integer, p_money_in integer) RETURNS TABLE(capacity_used integer, spent integer, summary jsonb, money_out integer)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_remaining integer := p_capacity;
  v_money integer := p_money_in;
  v_spent integer := 0;
  v_summary jsonb := '[]'::jsonb;
  v_policy record;
  v_sell_price integer;
  v_inventory numeric;
  v_needed integer;
  v_buy_amt integer;
BEGIN
  FOR v_policy IN
    SELECT tp.resource_key, tp.reserve_target
    FROM public.trade_policies tp
    WHERE tp.player_id = p_uid AND tp.mode = 'buy_to_reserve'
  LOOP
    IF v_remaining <= 0 THEN EXIT; END IF;
    SELECT tp.sell_price INTO v_sell_price
    FROM public.trader_prices tp
    WHERE tp.trader_key = p_trader_key
      AND tp.resource_key = v_policy.resource_key
      AND tp.is_active;
    IF NOT FOUND OR v_sell_price IS NULL THEN CONTINUE; END IF;

    SELECT COALESCE(quantity, 0) INTO v_inventory
    FROM public.inventories
    WHERE player_id = p_uid AND resource_key = v_policy.resource_key;
    IF v_inventory IS NULL THEN v_inventory := 0; END IF;

    v_needed := GREATEST(0, v_policy.reserve_target - FLOOR(v_inventory));
    IF v_needed <= 0 THEN CONTINUE; END IF;
    v_buy_amt := LEAST(v_needed, v_remaining);
    IF v_sell_price > 0 THEN
      v_buy_amt := LEAST(v_buy_amt, FLOOR(v_money / v_sell_price));
    END IF;
    IF v_buy_amt <= 0 THEN CONTINUE; END IF;

    INSERT INTO public.inventories (player_id, resource_key, quantity)
    VALUES (p_uid, v_policy.resource_key, v_buy_amt)
    ON CONFLICT (player_id, resource_key)
    DO UPDATE SET quantity = public.inventories.quantity + v_buy_amt, updated_at = now();

    v_spent := v_spent + (v_buy_amt * v_sell_price);
    v_money := v_money - (v_buy_amt * v_sell_price);
    v_remaining := v_remaining - v_buy_amt;
    v_summary := v_summary || jsonb_build_object(
      'type', 'buy',
      'resource', v_policy.resource_key,
      'quantity', v_buy_amt,
      'unit_price', v_sell_price,
      'total', v_buy_amt * v_sell_price
    );
    INSERT INTO public.trade_transactions
      (player_id, trader_key, resource_key, quantity, unit_price, total_price, transaction_type)
    VALUES
      (p_uid, p_trader_key, v_policy.resource_key, v_buy_amt, v_sell_price,
       v_buy_amt * v_sell_price, 'buy');
  END LOOP;

  capacity_used := p_capacity - v_remaining;
  spent := v_spent;
  summary := v_summary;
  money_out := v_money;
  RETURN NEXT;
END;
$$;


--
-- Name: _rtv_sell_phase(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._rtv_sell_phase(p_uid uuid, p_trader_key text, p_capacity integer) RETURNS TABLE(capacity_used integer, earned integer, summary jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_remaining integer := p_capacity;
  v_earned integer := 0;
  v_summary jsonb := '[]'::jsonb;
  v_policy record;
  v_buy_price integer;
  v_inventory numeric;
  v_surplus integer;
  v_sell_amt integer;
BEGIN
  FOR v_policy IN
    SELECT tp.resource_key, tp.reserve_target
    FROM public.trade_policies tp
    WHERE tp.player_id = p_uid AND tp.mode = 'sell_surplus'
  LOOP
    IF v_remaining <= 0 THEN EXIT; END IF;
    SELECT tp.buy_price INTO v_buy_price
    FROM public.trader_prices tp
    WHERE tp.trader_key = p_trader_key
      AND tp.resource_key = v_policy.resource_key
      AND tp.is_active;
    IF NOT FOUND OR v_buy_price IS NULL THEN CONTINUE; END IF;

    SELECT COALESCE(quantity, 0) INTO v_inventory
    FROM public.inventories
    WHERE player_id = p_uid AND resource_key = v_policy.resource_key;
    IF v_inventory IS NULL THEN v_inventory := 0; END IF;

    v_surplus := GREATEST(0, FLOOR(v_inventory) - v_policy.reserve_target);
    IF v_surplus <= 0 THEN CONTINUE; END IF;
    v_sell_amt := LEAST(v_surplus, v_remaining);
    IF v_sell_amt <= 0 THEN CONTINUE; END IF;

    UPDATE public.inventories
      SET quantity = quantity - v_sell_amt, updated_at = now()
      WHERE player_id = p_uid AND resource_key = v_policy.resource_key;

    v_earned := v_earned + (v_sell_amt * v_buy_price);
    v_remaining := v_remaining - v_sell_amt;
    v_summary := v_summary || jsonb_build_object(
      'type', 'sell',
      'resource', v_policy.resource_key,
      'quantity', v_sell_amt,
      'unit_price', v_buy_price,
      'total', v_sell_amt * v_buy_price
    );
    INSERT INTO public.trade_transactions
      (player_id, trader_key, resource_key, quantity, unit_price, total_price, transaction_type)
    VALUES
      (p_uid, p_trader_key, v_policy.resource_key, v_sell_amt, v_buy_price,
       v_sell_amt * v_buy_price, 'sell');
  END LOOP;

  capacity_used := p_capacity - v_remaining;
  earned := v_earned;
  summary := v_summary;
  RETURN NEXT;
END;
$$;


--
-- Name: _seed_resource_clusters(integer, integer, text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._seed_resource_clusters(p_chunk_x integer, p_chunk_y integer, p_resource_key text, p_cluster_count integer, p_min_walk integer, p_max_walk integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_x_start integer := p_chunk_x * 15;
  v_y_start integer := p_chunk_y * 15;
  v_idx integer;
  v_seed_dx integer;
  v_seed_dy integer;
  v_walk_steps integer;
  v_step integer;
  v_curr_dx integer;
  v_curr_dy integer;
  v_new_dx integer;
  v_new_dy integer;
  v_dir integer;
BEGIN
  FOR v_idx IN 1..p_cluster_count LOOP
    v_seed_dx := floor(random() * 15)::integer;
    v_seed_dy := floor(random() * 15)::integer;
    v_walk_steps := p_min_walk + floor(random() * (p_max_walk - p_min_walk + 1))::integer;
    v_curr_dx := v_seed_dx;
    v_curr_dy := v_seed_dy;

    UPDATE public.map_tiles
    SET resource_node_key = p_resource_key
    WHERE x = v_x_start + v_curr_dx AND y = v_y_start + v_curr_dy
      AND resource_node_key IS NULL;

    FOR v_step IN 1..v_walk_steps LOOP
      v_dir := floor(random() * 4)::integer;
      v_new_dx := v_curr_dx + CASE v_dir WHEN 0 THEN 1 WHEN 1 THEN -1 ELSE 0 END;
      v_new_dy := v_curr_dy + CASE v_dir WHEN 2 THEN 1 WHEN 3 THEN -1 ELSE 0 END;
      IF v_new_dx < 0 OR v_new_dx > 14 OR v_new_dy < 0 OR v_new_dy > 14 THEN
        v_curr_dx := v_seed_dx;
        v_curr_dy := v_seed_dy;
        CONTINUE;
      END IF;
      UPDATE public.map_tiles
      SET resource_node_key = p_resource_key
      WHERE x = v_x_start + v_new_dx AND y = v_y_start + v_new_dy
        AND resource_node_key IS NULL;
      v_curr_dx := v_new_dx;
      v_curr_dy := v_new_dy;
    END LOOP;
  END LOOP;
END;
$$;


--
-- Name: _tp_assert_unlocked(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._tp_assert_unlocked() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.is_trade_unlocked(v_uid) THEN
    RAISE EXCEPTION 'Trade locked: build at least 1 extractor, 1 food extractor, and 1 tier-1 house first.';
  END IF;
END;
$$;


--
-- Name: accept_trade(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_trade(p_offer_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_offer record;
  v_sender_money integer;
  v_recipient_money integer;
  v_resource_key text;
  v_qty numeric;
  v_have numeric;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  SELECT * INTO v_offer FROM public.player_trade_offers
    WHERE id = p_offer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Offer not found'; END IF;
  IF v_offer.to_player_id <> v_uid THEN
    RAISE EXCEPTION 'Only the recipient can accept this offer';
  END IF;
  IF v_offer.status <> 'pending' THEN
    RAISE EXCEPTION 'Offer is %', v_offer.status;
  END IF;

  -- Lock both player_profiles rows (consistent order to avoid deadlock).
  IF v_offer.from_player_id < v_offer.to_player_id THEN
    SELECT money INTO v_sender_money FROM public.player_profiles
      WHERE id = v_offer.from_player_id FOR UPDATE;
    SELECT money INTO v_recipient_money FROM public.player_profiles
      WHERE id = v_offer.to_player_id FOR UPDATE;
  ELSE
    SELECT money INTO v_recipient_money FROM public.player_profiles
      WHERE id = v_offer.to_player_id FOR UPDATE;
    SELECT money INTO v_sender_money FROM public.player_profiles
      WHERE id = v_offer.from_player_id FOR UPDATE;
  END IF;

  -- Re-validate balances at accept time.
  IF v_sender_money < v_offer.give_money THEN
    RAISE EXCEPTION 'Sender no longer has the offered money (need %, has %)',
      v_offer.give_money, v_sender_money;
  END IF;
  IF v_recipient_money < v_offer.receive_money THEN
    RAISE EXCEPTION 'You no longer have the requested money (need %, have %)',
      v_offer.receive_money, v_recipient_money;
  END IF;

  FOR v_resource_key, v_qty IN
    SELECT key, value::text::numeric FROM jsonb_each_text(v_offer.give_resources)
  LOOP
    SELECT COALESCE(quantity, 0) INTO v_have FROM public.inventories
      WHERE player_id = v_offer.from_player_id AND resource_key = v_resource_key;
    IF v_have IS NULL OR v_have < v_qty THEN
      RAISE EXCEPTION 'Sender no longer has enough % (need %, has %)',
        v_resource_key, v_qty, COALESCE(v_have, 0);
    END IF;
  END LOOP;
  FOR v_resource_key, v_qty IN
    SELECT key, value::text::numeric FROM jsonb_each_text(v_offer.receive_resources)
  LOOP
    SELECT COALESCE(quantity, 0) INTO v_have FROM public.inventories
      WHERE player_id = v_offer.to_player_id AND resource_key = v_resource_key;
    IF v_have IS NULL OR v_have < v_qty THEN
      RAISE EXCEPTION 'You no longer have enough % (need %, have %)',
        v_resource_key, v_qty, COALESCE(v_have, 0);
    END IF;
  END LOOP;

  -- Money: sender pays give_money, gains receive_money. Recipient
  -- mirror. (We've already locked both rows.)
  UPDATE public.player_profiles
    SET money = money - v_offer.give_money + v_offer.receive_money
    WHERE id = v_offer.from_player_id;
  UPDATE public.player_profiles
    SET money = money + v_offer.give_money - v_offer.receive_money
    WHERE id = v_offer.to_player_id;

  -- give_resources: sender → recipient
  FOR v_resource_key, v_qty IN
    SELECT key, value::text::numeric FROM jsonb_each_text(v_offer.give_resources)
  LOOP
    UPDATE public.inventories
      SET quantity = quantity - v_qty, updated_at = now()
      WHERE player_id = v_offer.from_player_id AND resource_key = v_resource_key;
    INSERT INTO public.inventories (player_id, resource_key, quantity)
    VALUES (v_offer.to_player_id, v_resource_key, v_qty)
    ON CONFLICT (player_id, resource_key) DO UPDATE SET
      quantity = public.inventories.quantity + EXCLUDED.quantity,
      updated_at = now();
  END LOOP;

  -- receive_resources: recipient → sender
  FOR v_resource_key, v_qty IN
    SELECT key, value::text::numeric FROM jsonb_each_text(v_offer.receive_resources)
  LOOP
    UPDATE public.inventories
      SET quantity = quantity - v_qty, updated_at = now()
      WHERE player_id = v_offer.to_player_id AND resource_key = v_resource_key;
    INSERT INTO public.inventories (player_id, resource_key, quantity)
    VALUES (v_offer.from_player_id, v_resource_key, v_qty)
    ON CONFLICT (player_id, resource_key) DO UPDATE SET
      quantity = public.inventories.quantity + EXCLUDED.quantity,
      updated_at = now();
  END LOOP;

  UPDATE public.player_trade_offers
    SET status = 'accepted', resolved_at = now()
    WHERE id = p_offer_id;

  RETURN json_build_object(
    'offer_id', p_offer_id,
    'status', 'accepted'
  );
END;
$$;


--
-- Name: allocate_district_chunk(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocate_district_chunk(p_player_id uuid, p_chunk_x integer, p_chunk_y integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_player record;
  v_x_start integer := p_chunk_x * 15;
  v_y_start integer := p_chunk_y * 15;
  v_dx integer;
  v_dy integer;
  v_resource_count integer;
  v_food_tile_key text;
  v_is_first_chunk boolean;
  v_axis_pos integer;
  v_cur_off integer;
  v_steps_left integer;
  v_can_drift boolean;
  v_drift_dir integer;
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.district_chunks
    WHERE chunk_x = p_chunk_x AND chunk_y = p_chunk_y
  ) THEN
    RAISE EXCEPTION 'Chunk (%, %) is already allocated', p_chunk_x, p_chunk_y;
  END IF;

  SELECT * INTO v_player FROM public.player_profiles WHERE id = p_player_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Player not found'; END IF;

  v_is_first_chunk := (v_player.chunks_owned = 0);
  v_food_tile_key := CASE v_player.industry_key
    WHEN 'timber' THEN 'orchard_grove'
    WHEN 'stone'  THEN 'pond'
    WHEN 'clay'   THEN 'garden_plot'
    WHEN 'iron'   THEN 'farmland'
  END;

  -- Lay down all 225 ground tiles. Critically: also wipe any leftover
  -- resource_node_key from a previous owner so the chunk reseeds clean.
  FOR v_dx IN 0..14 LOOP
    FOR v_dy IN 0..14 LOOP
      INSERT INTO public.map_tiles (
        x, y, terrain_type, resource_node_key, buildable, owner_player_id
      ) VALUES (
        v_x_start + v_dx, v_y_start + v_dy, 'ground', NULL, true, p_player_id
      )
      ON CONFLICT (x, y) DO UPDATE SET
        owner_player_id = p_player_id,
        terrain_type = 'ground',
        buildable = true,
        resource_node_key = NULL,
        claimed_by_building_id = NULL;
    END LOOP;
  END LOOP;

  -- Ore + food cluster seeding.
  PERFORM public._seed_resource_clusters(
    p_chunk_x, p_chunk_y, v_player.industry_key, 4, 6, 15);
  IF v_food_tile_key IS NOT NULL THEN
    PERFORM public._seed_resource_clusters(
      p_chunk_x, p_chunk_y, v_food_tile_key, 2, 4, 8);
  END IF;

  -- ── Curving horizontal highway: (0,7) → (14,7) ──
  v_axis_pos := 0; v_cur_off := 0;
  PERFORM public.place_pre_road(p_player_id, v_x_start + 0, v_y_start + 7);
  WHILE v_axis_pos < 14 LOOP
    v_steps_left := 14 - v_axis_pos;
    v_can_drift := abs(v_cur_off) + 1 < v_steps_left;
    IF v_can_drift AND random() < 0.35 THEN
      IF v_cur_off > 0 THEN
        v_drift_dir := CASE WHEN random() < 0.65 THEN -1 ELSE 1 END;
      ELSIF v_cur_off < 0 THEN
        v_drift_dir := CASE WHEN random() < 0.65 THEN 1 ELSE -1 END;
      ELSE
        v_drift_dir := CASE WHEN random() < 0.5 THEN 1 ELSE -1 END;
      END IF;
      IF abs(v_cur_off + v_drift_dir) > 3 THEN v_drift_dir := -v_drift_dir; END IF;
      v_cur_off := v_cur_off + v_drift_dir;
      PERFORM public.place_pre_road(p_player_id,
        v_x_start + v_axis_pos, v_y_start + 7 + v_cur_off);
    ELSE
      IF NOT v_can_drift AND v_cur_off != 0 THEN
        v_cur_off := v_cur_off - sign(v_cur_off);
        PERFORM public.place_pre_road(p_player_id,
          v_x_start + v_axis_pos, v_y_start + 7 + v_cur_off);
      ELSE
        v_axis_pos := v_axis_pos + 1;
        PERFORM public.place_pre_road(p_player_id,
          v_x_start + v_axis_pos, v_y_start + 7 + v_cur_off);
      END IF;
    END IF;
  END LOOP;
  WHILE v_cur_off != 0 LOOP
    v_cur_off := v_cur_off - sign(v_cur_off);
    PERFORM public.place_pre_road(p_player_id,
      v_x_start + 14, v_y_start + 7 + v_cur_off);
  END LOOP;

  -- ── Curving vertical highway: (7,0) → (7,14) ──
  v_axis_pos := 0; v_cur_off := 0;
  PERFORM public.place_pre_road(p_player_id, v_x_start + 7, v_y_start + 0);
  WHILE v_axis_pos < 14 LOOP
    v_steps_left := 14 - v_axis_pos;
    v_can_drift := abs(v_cur_off) + 1 < v_steps_left;
    IF v_can_drift AND random() < 0.35 THEN
      IF v_cur_off > 0 THEN
        v_drift_dir := CASE WHEN random() < 0.65 THEN -1 ELSE 1 END;
      ELSIF v_cur_off < 0 THEN
        v_drift_dir := CASE WHEN random() < 0.65 THEN 1 ELSE -1 END;
      ELSE
        v_drift_dir := CASE WHEN random() < 0.5 THEN 1 ELSE -1 END;
      END IF;
      IF abs(v_cur_off + v_drift_dir) > 3 THEN v_drift_dir := -v_drift_dir; END IF;
      v_cur_off := v_cur_off + v_drift_dir;
      PERFORM public.place_pre_road(p_player_id,
        v_x_start + 7 + v_cur_off, v_y_start + v_axis_pos);
    ELSE
      IF NOT v_can_drift AND v_cur_off != 0 THEN
        v_cur_off := v_cur_off - sign(v_cur_off);
        PERFORM public.place_pre_road(p_player_id,
          v_x_start + 7 + v_cur_off, v_y_start + v_axis_pos);
      ELSE
        v_axis_pos := v_axis_pos + 1;
        PERFORM public.place_pre_road(p_player_id,
          v_x_start + 7 + v_cur_off, v_y_start + v_axis_pos);
      END IF;
    END IF;
  END LOOP;
  WHILE v_cur_off != 0 LOOP
    v_cur_off := v_cur_off - sign(v_cur_off);
    PERFORM public.place_pre_road(p_player_id,
      v_x_start + 7 + v_cur_off, v_y_start + 14);
  END LOOP;

  IF v_is_first_chunk THEN
    UPDATE public.map_tiles
    SET terrain_type = 'city_center', buildable = false, resource_node_key = NULL
    WHERE x = v_x_start + 7 AND y = v_y_start + 7;
    UPDATE public.player_profiles
    SET home_x = v_x_start + 7, home_y = v_y_start + 7
    WHERE id = p_player_id;
  END IF;

  INSERT INTO public.district_chunks (chunk_x, chunk_y, owner_player_id)
  VALUES (p_chunk_x, p_chunk_y, p_player_id);

  UPDATE public.player_profiles
  SET chunks_owned = chunks_owned + 1
  WHERE id = p_player_id;

  SELECT COUNT(*) INTO v_resource_count
  FROM public.map_tiles
  WHERE owner_player_id = p_player_id
    AND x >= v_x_start AND x < v_x_start + 15
    AND y >= v_y_start AND y < v_y_start + 15
    AND resource_node_key IS NOT NULL;

  RETURN json_build_object(
    'chunk_x', p_chunk_x,
    'chunk_y', p_chunk_y,
    'tile_x_start', v_x_start,
    'tile_y_start', v_y_start,
    'resource_tiles', v_resource_count,
    'is_first_chunk', v_is_first_chunk
  );
END;
$$;


--
-- Name: black_market_trade(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.black_market_trade(p_resource_key text, p_quantity integer, p_direction text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_buy_from_player integer;
  v_sell_to_player integer;
  v_unit_price integer;
  v_total integer;
  v_available numeric;
  v_player_money integer;
  v_new_money integer;
BEGIN
  IF p_direction NOT IN ('buy', 'sell') THEN
    RAISE EXCEPTION 'Invalid direction: %. Must be buy or sell.', p_direction;
  END IF;
  IF p_quantity < 1 THEN
    RAISE EXCEPTION 'Quantity must be at least 1';
  END IF;

  PERFORM public.process_production();

  -- Sell-to-BM prices were 2/2/5/6/2/5/2/5/8/10/10. Cut by ~35%, floor 1.
  SELECT
    CASE p_resource_key
      WHEN 'timber'    THEN 1
      WHEN 'stone'     THEN 1
      WHEN 'lumber'    THEN 3
      WHEN 'brick'     THEN 4
      WHEN 'grain'     THEN 1
      WHEN 'flour'     THEN 3
      WHEN 'clay'      THEN 1
      WHEN 'pottery'   THEN 3
      WHEN 'bread'     THEN 5
      WHEN 'furniture' THEN 7
      WHEN 'statuary'  THEN 7
      ELSE NULL
    END,
    CASE p_resource_key
      WHEN 'timber'    THEN 10
      WHEN 'stone'     THEN 11
      WHEN 'lumber'    THEN 18
      WHEN 'brick'     THEN 20
      WHEN 'grain'     THEN 9
      WHEN 'flour'     THEN 16
      WHEN 'clay'      THEN 8
      WHEN 'pottery'   THEN 15
      WHEN 'bread'     THEN 22
      WHEN 'furniture' THEN 28
      WHEN 'statuary'  THEN 30
      ELSE NULL
    END
  INTO v_buy_from_player, v_sell_to_player;

  IF v_buy_from_player IS NULL THEN
    RAISE EXCEPTION 'Resource not available on black market: %', p_resource_key;
  END IF;

  IF p_direction = 'sell' THEN
    v_unit_price := v_buy_from_player;
    v_total := v_unit_price * p_quantity;

    SELECT COALESCE(quantity, 0) INTO v_available
    FROM public.inventories
    WHERE player_id = v_uid AND resource_key = p_resource_key;

    IF v_available IS NULL OR v_available < p_quantity THEN
      RAISE EXCEPTION 'Not enough % (have %, need %)', p_resource_key, COALESCE(v_available, 0), p_quantity;
    END IF;

    UPDATE public.inventories
    SET quantity = quantity - p_quantity, updated_at = now()
    WHERE player_id = v_uid AND resource_key = p_resource_key;

    UPDATE public.player_profiles
    SET money = money + v_total
    WHERE id = v_uid
    RETURNING money INTO v_new_money;

    INSERT INTO public.trade_transactions (player_id, trader_key, resource_key, quantity, unit_price, total_price, transaction_type)
    VALUES (v_uid, 'black_market', p_resource_key, p_quantity, v_unit_price, v_total, 'sell');

  ELSE
    v_unit_price := v_sell_to_player;
    v_total := v_unit_price * p_quantity;

    SELECT money INTO v_player_money
    FROM public.player_profiles WHERE id = v_uid;

    IF v_player_money < v_total THEN
      RAISE EXCEPTION 'Not enough money (have $%, need $%)', v_player_money, v_total;
    END IF;

    UPDATE public.player_profiles
    SET money = money - v_total
    WHERE id = v_uid
    RETURNING money INTO v_new_money;

    INSERT INTO public.inventories (player_id, resource_key, quantity)
    VALUES (v_uid, p_resource_key, p_quantity)
    ON CONFLICT (player_id, resource_key)
    DO UPDATE SET quantity = inventories.quantity + p_quantity, updated_at = now();

    INSERT INTO public.trade_transactions (player_id, trader_key, resource_key, quantity, unit_price, total_price, transaction_type)
    VALUES (v_uid, 'black_market', p_resource_key, p_quantity, v_unit_price, v_total, 'buy');
  END IF;

  RETURN json_build_object(
    'direction', p_direction,
    'resource', p_resource_key,
    'quantity', p_quantity,
    'unit_price', v_unit_price,
    'total_price', v_total,
    'money', v_new_money,
    'inventory', COALESCE(
      (SELECT json_object_agg(resource_key, quantity)
       FROM public.inventories WHERE player_id = v_uid),
      '{}'::json
    )
  );
END;
$_$;


--
-- Name: cancel_trade(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_trade(p_offer_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_offer record;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT * INTO v_offer FROM public.player_trade_offers
    WHERE id = p_offer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Offer not found'; END IF;
  IF v_offer.from_player_id <> v_uid THEN
    RAISE EXCEPTION 'Only the sender can cancel this offer';
  END IF;
  IF v_offer.status <> 'pending' THEN
    RAISE EXCEPTION 'Offer is %', v_offer.status;
  END IF;
  UPDATE public.player_trade_offers
    SET status = 'cancelled', resolved_at = now()
    WHERE id = p_offer_id;
END;
$$;


--
-- Name: choose_industry(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.choose_industry(p_display_name text, p_industry_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_profile record;
  v_chunks_owned integer;
  v_row integer;
BEGIN
  IF p_industry_key NOT IN ('timber', 'stone', 'iron', 'clay') THEN
    RAISE EXCEPTION 'Invalid industry. Choose timber, stone, iron, or clay.';
  END IF;
  IF length(trim(p_display_name)) < 2 THEN
    RAISE EXCEPTION 'Display name must be at least 2 characters.';
  END IF;

  INSERT INTO public.player_profiles (
    id, display_name, industry_key, money, worker_capacity, workers_used, chunks_owned
  ) VALUES (
    v_uid, trim(p_display_name), p_industry_key, 500, 5, 0, 0
  )
  ON CONFLICT (id) DO UPDATE SET
    display_name = trim(EXCLUDED.display_name),
    industry_key = EXCLUDED.industry_key,
    updated_at = now();

  INSERT INTO public.inventories (player_id, resource_key, quantity) VALUES
    (v_uid, 'timber', 0),      (v_uid, 'lumber', 0),
    (v_uid, 'stone', 0),       (v_uid, 'brick', 0),
    (v_uid, 'iron', 0),        (v_uid, 'iron_ingot', 0),
    (v_uid, 'tools', 0),
    (v_uid, 'grain', 0),       (v_uid, 'flour', 0),
    (v_uid, 'clay', 0),        (v_uid, 'pottery', 0),
    (v_uid, 'tiles', 0),
    (v_uid, 'bread', 0),       (v_uid, 'furniture', 0),
    (v_uid, 'statuary', 0),
    (v_uid, 'berries', 0),     (v_uid, 'wine', 0),
    (v_uid, 'fish', 0),        (v_uid, 'smoked_fish', 0),
    (v_uid, 'vegetables', 0),  (v_uid, 'preserves', 0),
    (v_uid, 'spirits', 0),     (v_uid, 'caviar', 0),
    (v_uid, 'spices', 0),      (v_uid, 'ale', 0),
    (v_uid, 'charcoal', 0),    (v_uid, 'lime', 0),
    (v_uid, 'glass', 0),       (v_uid, 'nails', 0),
    (v_uid, 'cabinets', 0),    (v_uid, 'monuments', 0),
    (v_uid, 'mosaics', 0),     (v_uid, 'machinery', 0)
  ON CONFLICT (player_id, resource_key) DO NOTHING;

  SELECT chunks_owned INTO v_chunks_owned
  FROM public.player_profiles WHERE id = v_uid;

  IF v_chunks_owned = 0 THEN
    v_row := public.next_starter_row();
    UPDATE public.player_profiles SET reserved_row = v_row WHERE id = v_uid;
    PERFORM public.allocate_district_chunk(v_uid, 0, v_row);
  END IF;

  SELECT * INTO v_profile FROM public.player_profiles WHERE id = v_uid;

  RETURN json_build_object(
    'id', v_profile.id,
    'display_name', v_profile.display_name,
    'industry_key', v_profile.industry_key,
    'money', v_profile.money,
    'worker_capacity', v_profile.worker_capacity,
    'workers_used', v_profile.workers_used,
    'chunks_owned', v_profile.chunks_owned,
    'home_x', v_profile.home_x,
    'home_y', v_profile.home_y,
    'reserved_row', v_profile.reserved_row
  );
END;
$$;


--
-- Name: city_rep_tier(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.city_rep_tier(p_trader_key text) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_rep numeric;
BEGIN
  v_rep := public.city_reputation(p_trader_key);
  IF v_rep >= 1000 THEN RETURN 4;
  ELSIF v_rep >= 400 THEN RETURN 3;
  ELSIF v_rep >= 150 THEN RETURN 2;
  ELSIF v_rep >= 50  THEN RETURN 1;
  ELSE RETURN 0;
  END IF;
END;
$$;


--
-- Name: city_reputation(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.city_reputation(p_trader_key text) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_num numeric := 0;
  v_den numeric := 0;
  r record;
BEGIN
  FOR r IN
    SELECT pp.id AS player_id,
           COALESCE(tr.reputation, 0) AS rep,
           public.district_weight(pp.id) AS w
    FROM public.player_profiles pp
    LEFT JOIN public.trader_relationships tr
      ON tr.player_id = pp.id AND tr.trader_key = p_trader_key
  LOOP
    v_num := v_num + (r.rep * r.w);
    v_den := v_den + r.w;
  END LOOP;
  IF v_den = 0 THEN RETURN 0; END IF;
  RETURN v_num / v_den;
END;
$$;


--
-- Name: clear_resource_tile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_resource_tile(p_tile_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_tile record;
BEGIN
  SELECT * INTO v_tile FROM public.map_tiles WHERE id = p_tile_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Tile not found'; END IF;
  IF v_tile.owner_player_id IS NULL OR v_tile.owner_player_id <> v_uid THEN
    RAISE EXCEPTION 'Cannot clear a resource tile you do not own';
  END IF;
  IF v_tile.resource_node_key IS NULL THEN
    RAISE EXCEPTION 'Tile has no resource to clear';
  END IF;
  IF v_tile.claimed_by_building_id IS NOT NULL THEN
    RAISE EXCEPTION 'Demolish the extractor targeting this tile before clearing it';
  END IF;
  IF v_tile.occupied_building_id IS NOT NULL THEN
    RAISE EXCEPTION 'Demolish the building on this tile before clearing it';
  END IF;
  UPDATE public.map_tiles SET resource_node_key = NULL WHERE id = p_tile_id;
  RETURN json_build_object(
    'tile_id', p_tile_id,
    'cleared_resource', v_tile.resource_node_key,
    'x', v_tile.x,
    'y', v_tile.y
  );
END;
$$;


--
-- Name: complete_onboarding(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_onboarding(p_display_name text, p_specialization_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_player_id uuid;
  v_world_id uuid;
  v_district_id uuid;
  v_email text;
  v_district_slot record;
begin
  v_player_id := auth.uid();
  if v_player_id is null then
    raise exception 'Not authenticated';
  end if;

  if p_display_name is null or length(trim(p_display_name)) < 2 then
    raise exception 'Display name must be at least 2 characters';
  end if;
  if length(trim(p_display_name)) > 24 then
    raise exception 'Display name must be 24 characters or fewer';
  end if;

  if p_specialization_key not in ('timber', 'stone', 'grain', 'clay', 'iron_ore') then
    raise exception 'Invalid specialization. Must be timber, stone, grain, clay, or iron_ore.';
  end if;

  if exists (
    select 1 from public.player_profiles
    where id = v_player_id and specialization_key is not null
  ) then
    raise exception 'Player has already completed onboarding';
  end if;

  select id into v_world_id
  from public.worlds
  where slug = 'alpha-world' and status = 'active'
  limit 1;

  if v_world_id is null then
    raise exception 'No active world found';
  end if;

  select email into v_email
  from auth.users
  where id = v_player_id;

  -- Upsert player profile first (needed before district FK)
  insert into public.player_profiles (id, email, display_name, specialization_key, home_world_id, home_district_id)
  values (v_player_id, v_email, trim(p_display_name), p_specialization_key, v_world_id, null)
  on conflict (id) do update set
    display_name = trim(p_display_name),
    specialization_key = p_specialization_key,
    home_world_id = v_world_id;

  -- Auto-create a Tier 1 district
  select
    (s.slot_index % 4) * 8 as ox,
    (s.slot_index / 4) * 8 as oy
  into v_district_slot
  from generate_series(0, 15) as s(slot_index)
  where not exists (
    select 1 from public.districts d
    where d.world_id = v_world_id
      and d.origin_x = (s.slot_index % 4) * 8
      and d.origin_y = (s.slot_index / 4) * 8
  )
  order by s.slot_index
  limit 1;

  if v_district_slot is null then
    raise exception 'No district slots available in the world';
  end if;

  insert into public.districts (world_id, owner_player_id, name, origin_x, origin_y, width, height, tier, status)
  values (v_world_id, v_player_id, trim(p_display_name) || '''s District', v_district_slot.ox, v_district_slot.oy, 8, 8, 1, 'active')
  returning id into v_district_id;

  -- Link district back to profile
  update public.player_profiles
  set home_district_id = v_district_id
  where id = v_player_id;

  -- Create treasury
  insert into public.player_treasuries (player_id, gold, income_per_tick, expenses_per_tick)
  values (v_player_id, 500, 0, 0)
  on conflict (player_id) do nothing;

  -- Create inventory rows for all 15 v1 goods
  insert into public.player_inventories (player_id, resource_key, amount)
  values
    (v_player_id, 'timber', 0),
    (v_player_id, 'stone', 0),
    (v_player_id, 'grain', 0),
    (v_player_id, 'clay', 0),
    (v_player_id, 'iron_ore', 0),
    (v_player_id, 'wood_planks', 0),
    (v_player_id, 'cut_stone', 0),
    (v_player_id, 'bricks', 0),
    (v_player_id, 'iron_bars', 0),
    (v_player_id, 'flour', 0),
    (v_player_id, 'bread', 0),
    (v_player_id, 'tools', 0),
    (v_player_id, 'pottery', 0),
    (v_player_id, 'furniture', 0),
    (v_player_id, 'fine_goods', 0)
  on conflict (player_id, resource_key) do nothing;

  -- Create population state
  insert into public.population_state (player_id, district_id, total_population, housed_population, employed_population, unhoused_population, happiness)
  values (v_player_id, v_district_id, 0, 0, 0, 0, 50)
  on conflict (player_id) do nothing;

  -- Seed district tiles with resource distribution
  perform public.seed_district_tiles(v_district_id, p_specialization_key);

  return jsonb_build_object(
    'success', true,
    'player_id', v_player_id,
    'display_name', trim(p_display_name),
    'specialization', p_specialization_key,
    'world_id', v_world_id,
    'district_id', v_district_id,
    'district_tier', 1
  );
end;
$$;


--
-- Name: compute_crime(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_crime(p_uid uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_population numeric;
  v_uncovered integer;
  v_taverns integer;
  v_score numeric;
BEGIN
  SELECT population INTO v_population FROM public.player_profiles WHERE id = p_uid;
  IF v_population IS NULL THEN v_population := 5; END IF;

  SELECT COUNT(*) INTO v_uncovered
  FROM public.buildings h
  JOIN public.building_types bt ON bt.key = h.building_type_key
  WHERE h.player_id = p_uid AND h.status = 'active' AND bt.category = 'housing'
    AND NOT EXISTS (
      SELECT 1 FROM public.buildings p
      JOIN public.building_types pt ON pt.key = p.building_type_key
      WHERE p.player_id = p_uid AND p.status = 'active' AND pt.category = 'police'
        AND p.is_staffed
        AND ABS(p.x - h.x) + ABS(p.y - h.y) <= pt.coverage_radius
    );

  SELECT COUNT(*) INTO v_taverns
  FROM public.buildings b
  WHERE b.player_id = p_uid AND b.status = 'active' AND b.building_type_key = 'tavern';

  v_score := 10
    + 4 * v_uncovered
    + LEAST(20, FLOOR(v_population / 10))
    + 1 * v_taverns;

  RETURN LEAST(100, GREATEST(0, v_score));
END;
$$;


--
-- Name: compute_happiness(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_happiness(p_uid uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_base constant numeric := 30;
  v_services integer := 0;
  v_avg_tier numeric := 0;
  v_food_variety integer := 0;
  v_tax_count integer := 0;
  v_workers_needed integer := 0;
  v_worker_capacity integer := 0;
  v_staffing_ratio numeric := 1.0;
  v_crime numeric := 0;
  v_crime_penalty numeric := 0;
  v_score numeric;
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.buildings b
    JOIN public.building_types bt ON bt.key = b.building_type_key
    WHERE b.player_id = p_uid AND b.status = 'active' AND bt.key = 'well'
      AND public.has_road_access(p_uid, b.x, b.y)
  ) THEN v_services := v_services + 1; END IF;

  v_services := v_services + (
    SELECT COUNT(DISTINCT bt.key) FROM public.buildings b
    JOIN public.building_types bt ON bt.key = b.building_type_key
    WHERE b.player_id = p_uid AND b.status = 'active'
      AND bt.category = 'service' AND bt.key <> 'well'
      AND public.has_road_access(p_uid, b.x, b.y)
      AND COALESCE((SELECT quantity FROM public.inventories i
                    WHERE i.player_id = p_uid AND i.resource_key = bt.input_resource_key), 0) > 0
      AND (bt.input_resource_key_2 IS NULL
           OR COALESCE((SELECT quantity FROM public.inventories i
                        WHERE i.player_id = p_uid AND i.resource_key = bt.input_resource_key_2), 0) > 0)
  );

  SELECT COALESCE(AVG(b.housing_tier), 0) INTO v_avg_tier
  FROM public.buildings b
  JOIN public.building_types bt ON bt.key = b.building_type_key
  WHERE b.player_id = p_uid AND b.status = 'active' AND bt.category = 'housing';

  SELECT COUNT(*) INTO v_food_variety
  FROM public.inventories i
  JOIN public.resources r ON r.key = i.resource_key
  WHERE i.player_id = p_uid AND r.is_food AND i.quantity > 0;

  SELECT COUNT(*) INTO v_tax_count
  FROM public.buildings b
  JOIN public.building_types bt ON bt.key = b.building_type_key
  WHERE b.player_id = p_uid AND b.status = 'active' AND bt.category = 'tax';

  SELECT worker_capacity INTO v_worker_capacity
  FROM public.player_profiles WHERE id = p_uid;
  v_workers_needed := public._pp_workers_needed(p_uid);
  IF v_workers_needed > 0 THEN
    v_staffing_ratio := LEAST(1.0, v_worker_capacity::numeric / v_workers_needed::numeric);
  END IF;

  -- Crime penalty: high crime steals happiness, which (asymmetric model)
  -- pushes citizens to emigrate.
  v_crime := public.compute_crime(p_uid);
  v_crime_penalty := FLOOR(v_crime / 5);

  v_score :=
    v_base
    + 3 * v_services
    + 2 * v_avg_tier
    + LEAST(15, v_food_variety * 2)
    - 3 * v_tax_count
    + 20 * v_staffing_ratio
    - v_crime_penalty;

  RETURN json_build_object(
    'happiness', LEAST(100, GREATEST(0, v_score)),
    'breakdown', json_build_object(
      'base', v_base,
      'services', v_services,
      'avg_tier', v_avg_tier,
      'food_variety', v_food_variety,
      'tax_count', v_tax_count,
      'worker_capacity', v_worker_capacity,
      'workers_needed', v_workers_needed,
      'staffing_ratio', v_staffing_ratio,
      'crime', v_crime,
      'crime_penalty', v_crime_penalty
    )
  );
END;
$$;


--
-- Name: decay_reputations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decay_reputations() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  r record;
  v_now timestamptz := now();
  v_days numeric;
  v_factor numeric;
  v_count integer := 0;
BEGIN
  FOR r IN
    SELECT * FROM public.trader_relationships
    WHERE last_decay_at + interval '24 hours' < v_now
      AND (last_donation_at IS NULL OR last_donation_at + interval '7 days' < v_now)
      AND reputation > 0
    FOR UPDATE
  LOOP
    v_days := EXTRACT(EPOCH FROM (v_now - r.last_decay_at)) / 86400.0;
    v_factor := POWER(0.98, v_days);
    UPDATE public.trader_relationships
      SET reputation = GREATEST(0, reputation * v_factor),
          last_decay_at = v_now
      WHERE player_id = r.player_id AND trader_key = r.trader_key;
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


--
-- Name: district_weight(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.district_weight(p_player_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_total integer;
BEGIN
  SELECT COALESCE(SUM(htc.workers), 0)::integer INTO v_total
  FROM public.buildings b
  JOIN public.building_types bt ON bt.key = b.building_type_key
  JOIN public.housing_tier_config htc ON htc.tier = b.housing_tier
  WHERE b.player_id = p_player_id AND b.status = 'active'
    AND bt.category = 'housing';
  RETURN GREATEST(1, v_total);
END;
$$;


--
-- Name: donate_to_mission(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.donate_to_mission(p_mission_id uuid, p_qty integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_mission record;
  v_have numeric;
  v_now timestamptz := now();
  v_speed_mult numeric := 1.0;
  v_elapsed_min numeric;
  v_total integer;
  d record;
  v_rep_per_unit numeric;
  v_award numeric;
  v_per_player_award jsonb := '{}'::jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_qty IS NULL OR p_qty <= 0 THEN RAISE EXCEPTION 'Donation must be positive'; END IF;

  -- Lock the mission row.
  SELECT * INTO v_mission FROM public.trader_missions
    WHERE id = p_mission_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Mission not found'; END IF;
  IF v_mission.status <> 'open' THEN
    RAISE EXCEPTION 'Mission is %', v_mission.status;
  END IF;

  -- Check player has enough.
  SELECT COALESCE(quantity, 0) INTO v_have
  FROM public.inventories
  WHERE player_id = v_uid AND resource_key = v_mission.resource_key;
  IF v_have IS NULL THEN v_have := 0; END IF;
  IF v_have < p_qty THEN
    RAISE EXCEPTION 'You only have % %', FLOOR(v_have), v_mission.resource_key;
  END IF;

  -- Cap donation to remaining target (don't accept more than needed).
  IF p_qty > (v_mission.target_qty - v_mission.current_qty) THEN
    p_qty := v_mission.target_qty - v_mission.current_qty;
  END IF;
  IF p_qty <= 0 THEN
    RAISE EXCEPTION 'Mission already fulfilled';
  END IF;

  -- Debit inventory.
  UPDATE public.inventories
    SET quantity = quantity - p_qty, updated_at = now()
    WHERE player_id = v_uid AND resource_key = v_mission.resource_key;

  -- Record the donation.
  INSERT INTO public.trader_mission_donations (mission_id, player_id, qty)
  VALUES (p_mission_id, v_uid, p_qty);

  -- Advance the mission.
  UPDATE public.trader_missions
    SET current_qty = current_qty + p_qty
    WHERE id = p_mission_id
    RETURNING current_qty INTO v_mission.current_qty;

  -- If mission is now full, close it and distribute reputation.
  IF v_mission.current_qty >= v_mission.target_qty THEN
    -- Speed bonus: 1.5 → 1.0 over the soft-deadline window.
    v_elapsed_min := EXTRACT(EPOCH FROM (v_now - v_mission.created_at)) / 60.0;
    v_speed_mult := GREATEST(1.0, LEAST(1.5,
      1.5 - (v_elapsed_min / NULLIF(EXTRACT(EPOCH FROM (v_mission.soft_deadline - v_mission.created_at)) / 60.0, 0)) * 0.5));

    -- Per-unit reward = 1.0 × speed multiplier. Player's share = their qty × per-unit reward.
    v_rep_per_unit := v_speed_mult;

    FOR d IN
      SELECT player_id, SUM(qty) AS qty
      FROM public.trader_mission_donations
      WHERE mission_id = p_mission_id
      GROUP BY player_id
    LOOP
      v_award := d.qty::numeric * v_rep_per_unit;
      INSERT INTO public.trader_relationships (player_id, trader_key, reputation, last_donation_at, last_decay_at)
      VALUES (d.player_id, v_mission.trader_key, v_award, v_now, v_now)
      ON CONFLICT (player_id, trader_key) DO UPDATE
        SET reputation = public.trader_relationships.reputation + EXCLUDED.reputation,
            last_donation_at = EXCLUDED.last_donation_at;
      v_per_player_award := v_per_player_award || jsonb_build_object(d.player_id::text, v_award);
    END LOOP;

    UPDATE public.trader_missions
      SET status = 'fulfilled', resolved_at = v_now
      WHERE id = p_mission_id;
  END IF;

  RETURN json_build_object(
    'mission_id', p_mission_id,
    'donated_qty', p_qty,
    'current_qty', v_mission.current_qty,
    'target_qty', v_mission.target_qty,
    'fulfilled', v_mission.current_qty >= v_mission.target_qty,
    'speed_multiplier', v_speed_mult,
    'rep_awards', v_per_player_award
  );
END;
$$;


--
-- Name: expand_district(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expand_district(p_chunk_x integer, p_chunk_y integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_player record;
  v_cost integer;
  v_alloc json;
  v_base_cost integer := 1000;
  v_is_candidate boolean;
BEGIN
  SELECT * INTO v_player FROM public.player_profiles WHERE id = v_uid;
  IF NOT FOUND THEN RAISE EXCEPTION 'Player not found'; END IF;

  v_cost := v_base_cost * v_player.chunks_owned * v_player.chunks_owned;

  IF v_player.money < v_cost THEN
    RAISE EXCEPTION 'Not enough money to expand (need %, have %)',
      v_cost, v_player.money;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.expansion_candidates(v_uid) ec
    WHERE ec.chunk_x = p_chunk_x AND ec.chunk_y = p_chunk_y
  ) INTO v_is_candidate;

  IF NOT v_is_candidate THEN
    RAISE EXCEPTION 'Chunk (%, %) is not a valid expansion candidate', p_chunk_x, p_chunk_y;
  END IF;

  v_alloc := public.allocate_district_chunk(v_uid, p_chunk_x, p_chunk_y);

  UPDATE public.player_profiles
  SET money = money - v_cost
  WHERE id = v_uid
  RETURNING * INTO v_player;

  INSERT INTO public.cash_transactions (player_id, source, amount, context)
  VALUES (v_uid, 'expansion_cost', -v_cost,
          jsonb_build_object('chunk_x', p_chunk_x, 'chunk_y', p_chunk_y));

  RETURN json_build_object(
    'chunk_x', p_chunk_x,
    'chunk_y', p_chunk_y,
    'cost', v_cost,
    'money', v_player.money,
    'chunks_owned', v_player.chunks_owned,
    'allocation', v_alloc
  );
END;
$$;


--
-- Name: expansion_candidates(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expansion_candidates(p_player_id uuid) RETURNS TABLE(chunk_x integer, chunk_y integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  WITH neighbors AS (
    -- All chunks orthogonally adjacent to any chunk owned by the player.
    SELECT DISTINCT cand_x, cand_y FROM (
      SELECT dc.chunk_x + 1 AS cand_x, dc.chunk_y AS cand_y FROM public.district_chunks dc WHERE dc.owner_player_id = p_player_id
      UNION ALL
      SELECT dc.chunk_x - 1, dc.chunk_y FROM public.district_chunks dc WHERE dc.owner_player_id = p_player_id
      UNION ALL
      SELECT dc.chunk_x, dc.chunk_y + 1 FROM public.district_chunks dc WHERE dc.owner_player_id = p_player_id
      UNION ALL
      SELECT dc.chunk_x, dc.chunk_y - 1 FROM public.district_chunks dc WHERE dc.owner_player_id = p_player_id
    ) raw
  ),
  reserved_rows AS (
    SELECT pp.reserved_row AS row
    FROM public.player_profiles pp
    WHERE pp.reserved_row IS NOT NULL AND pp.id <> p_player_id
  )
  SELECT n.cand_x, n.cand_y
  FROM neighbors n
  -- Exclude already-owned chunks.
  WHERE NOT EXISTS (
    SELECT 1 FROM public.district_chunks dc2
    WHERE dc2.chunk_x = n.cand_x AND dc2.chunk_y = n.cand_y
  )
  -- Exclude other players' reserved rows.
  AND NOT EXISTS (
    SELECT 1 FROM reserved_rows rr WHERE rr.row = n.cand_y
  )
  ORDER BY n.cand_y, n.cand_x;
END;
$$;


--
-- Name: expire_old_missions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_old_missions() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  m record;
  d record;
  v_total integer;
  v_count integer := 0;
  v_rep_award numeric;
BEGIN
  FOR m IN
    SELECT * FROM public.trader_missions
    WHERE status = 'open' AND expires_at < now()
    FOR UPDATE
  LOOP
    -- Total contributed to this mission.
    SELECT COALESCE(SUM(qty), 0) INTO v_total
    FROM public.trader_mission_donations
    WHERE mission_id = m.id;

    -- Award partial reputation: 1.0 per unit of target_qty contributed
    -- (full mission completion = 1.0 × target_qty rep awarded total,
    -- distributed proportionally; partial fulfillment = proportionally less).
    -- No speed bonus for expired missions.
    IF v_total > 0 THEN
      FOR d IN
        SELECT player_id, SUM(qty) AS qty
        FROM public.trader_mission_donations
        WHERE mission_id = m.id
        GROUP BY player_id
      LOOP
        -- Per-unit reward = 1.0 (matches base rep-per-unit). Player's
        -- share = their qty * 1.0.
        v_rep_award := d.qty::numeric;
        INSERT INTO public.trader_relationships (player_id, trader_key, reputation, last_donation_at, last_decay_at)
        VALUES (d.player_id, m.trader_key, v_rep_award, now(), now())
        ON CONFLICT (player_id, trader_key) DO UPDATE
          SET reputation = public.trader_relationships.reputation + EXCLUDED.reputation,
              last_donation_at = EXCLUDED.last_donation_at;
      END LOOP;
    END IF;

    UPDATE public.trader_missions
      SET status = 'expired', resolved_at = now()
      WHERE id = m.id;
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


--
-- Name: find_nearest_unclaimed_resource(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_nearest_unclaimed_resource(p_player_id uuid, p_ex integer, p_ey integer) RETURNS TABLE(target_x integer, target_y integer, path_length integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_player record;
  v_resource_key text;
  v_state jsonb := '{}'::jsonb;
  v_cur_key text;
  v_cur_dist integer;
  v_cur_x integer;
  v_cur_y integer;
  v_neighbor_x integer;
  v_neighbor_y integer;
  v_neighbor_key text;
  v_neighbor_cost integer;
  v_existing_dist integer;
  v_is_road boolean;
  v_neighbor_walkable boolean;
  v_is_resource boolean;
  v_dx int[] := ARRAY[-1, 1, 0, 0];
  v_dy int[] := ARRAY[0, 0, -1, 1];
  v_i integer;
  v_iters integer := 0;
  v_road_cost constant integer := 1;
  v_offroad_cost constant integer := 3;
BEGIN
  SELECT * INTO v_player FROM public.player_profiles WHERE id = p_player_id;
  IF NOT FOUND THEN RETURN; END IF;
  v_resource_key := v_player.industry_key;
  v_state := jsonb_build_object(
    p_ex || ',' || p_ey,
    jsonb_build_object('x', p_ex, 'y', p_ey, 'd', 0, 'v', false)
  );
  WHILE v_iters < 2000 LOOP
    v_iters := v_iters + 1;
    SELECT key, (value->>'x')::int, (value->>'y')::int, (value->>'d')::int
    INTO v_cur_key, v_cur_x, v_cur_y, v_cur_dist
    FROM jsonb_each(v_state)
    WHERE (value->>'v')::boolean = false
    ORDER BY (value->>'d')::int ASC LIMIT 1;
    IF v_cur_key IS NULL THEN RETURN; END IF;
    v_state := jsonb_set(v_state, ARRAY[v_cur_key, 'v'], 'true'::jsonb);
    IF NOT (v_cur_x = p_ex AND v_cur_y = p_ey) THEN
      SELECT EXISTS (
        SELECT 1 FROM public.map_tiles mt
        WHERE mt.x = v_cur_x AND mt.y = v_cur_y
          AND mt.owner_player_id = p_player_id
          AND mt.resource_node_key = v_resource_key
          AND mt.claimed_by_building_id IS NULL
          AND mt.occupied_building_id IS NULL
      ) INTO v_is_resource;
      IF v_is_resource THEN
        target_x := v_cur_x; target_y := v_cur_y; path_length := v_cur_dist;
        RETURN NEXT; RETURN;
      END IF;
    END IF;
    FOR v_i IN 1..4 LOOP
      v_neighbor_x := v_cur_x + v_dx[v_i];
      v_neighbor_y := v_cur_y + v_dy[v_i];
      v_neighbor_key := v_neighbor_x || ',' || v_neighbor_y;
      SELECT EXISTS (
        SELECT 1 FROM public.buildings b
        JOIN public.building_types bt ON bt.key = b.building_type_key
        WHERE b.x = v_neighbor_x AND b.y = v_neighbor_y
          AND bt.category = 'road' AND b.status = 'active'
          AND b.player_id = p_player_id
      ) INTO v_is_road;
      IF v_is_road THEN
        v_neighbor_cost := v_road_cost;
        v_neighbor_walkable := true;
      ELSE
        SELECT EXISTS (
          SELECT 1 FROM public.map_tiles mt
          WHERE mt.x = v_neighbor_x AND mt.y = v_neighbor_y
            AND mt.owner_player_id = p_player_id
            AND mt.occupied_building_id IS NULL
        ) INTO v_neighbor_walkable;
        v_neighbor_cost := v_offroad_cost;
      END IF;
      IF NOT v_neighbor_walkable THEN CONTINUE; END IF;
      IF v_state ? v_neighbor_key THEN
        IF NOT ((v_state->v_neighbor_key->>'v')::boolean) THEN
          v_existing_dist := (v_state->v_neighbor_key->>'d')::int;
          IF v_cur_dist + v_neighbor_cost < v_existing_dist THEN
            v_state := jsonb_set(v_state, ARRAY[v_neighbor_key, 'd'],
              to_jsonb(v_cur_dist + v_neighbor_cost));
          END IF;
        END IF;
      ELSE
        v_state := v_state || jsonb_build_object(
          v_neighbor_key,
          jsonb_build_object('x', v_neighbor_x, 'y', v_neighbor_y,
            'd', v_cur_dist + v_neighbor_cost, 'v', false)
        );
      END IF;
    END LOOP;
  END LOOP;
  RETURN;
END;
$$;


--
-- Name: get_active_missions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_missions() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_open jsonb := '[]'::jsonb;
  v_quiet jsonb := '[]'::jsonb;
  m record;
  q record;
BEGIN
  -- Lazy housekeeping — same pattern as resolve_trader_visit.
  PERFORM public.expire_old_missions();
  PERFORM public.roll_trader_missions();
  PERFORM public.decay_reputations();

  -- Currently open missions.
  FOR m IN
    SELECT tm.*, t.name AS trader_name, t.specialty_template
    FROM public.trader_missions tm
    JOIN public.traders t ON t.key = tm.trader_key
    WHERE tm.status = 'open'
    ORDER BY tm.created_at DESC
  LOOP
    v_open := v_open || jsonb_build_object(
      'id', m.id,
      'trader_key', m.trader_key,
      'trader_name', m.trader_name,
      'resource_key', m.resource_key,
      'target_qty', m.target_qty,
      'current_qty', m.current_qty,
      'soft_deadline', m.soft_deadline,
      'expires_at', m.expires_at,
      'created_at', m.created_at,
      'your_donated_qty', COALESCE((
        SELECT SUM(qty) FROM public.trader_mission_donations
        WHERE mission_id = m.id AND player_id = v_uid
      ), 0)
    );
  END LOOP;

  -- Quiet traders: active, no open mission right now. Compute when
  -- their next request becomes eligible (last_resolved + cooldown).
  -- roll_trader_missions ran above, so any trader still in this set
  -- is genuinely mid-cooldown.
  FOR q IN
    SELECT t.key, t.name, t.mission_cooldown_minutes,
           (SELECT MAX(resolved_at) FROM public.trader_missions
              WHERE trader_key = t.key AND status <> 'open') AS last_resolved
    FROM public.traders t
    WHERE t.is_active
      AND NOT EXISTS (
        SELECT 1 FROM public.trader_missions
        WHERE trader_key = t.key AND status = 'open'
      )
    ORDER BY t.name
  LOOP
    v_quiet := v_quiet || jsonb_build_object(
      'trader_key', q.key,
      'trader_name', q.name,
      'last_resolved_at', q.last_resolved,
      'next_eligible_at',
        CASE WHEN q.last_resolved IS NULL THEN now()
             ELSE q.last_resolved + (q.mission_cooldown_minutes || ' minutes')::interval
        END,
      'cooldown_minutes', q.mission_cooldown_minutes
    );
  END LOOP;

  RETURN json_build_object('open', v_open, 'quiet', v_quiet);
END;
$$;


--
-- Name: get_player_trade_view(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_player_trade_view(p_player_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_money integer;
  v_display text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_player_id IS NULL THEN
    RAISE EXCEPTION 'Player ID required';
  END IF;

  SELECT money, display_name INTO v_money, v_display
  FROM public.player_profiles WHERE id = p_player_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Player not found';
  END IF;

  RETURN json_build_object(
    'player_id', p_player_id,
    'display_name', v_display,
    'money', v_money,
    'inventory', COALESCE(
      (SELECT json_object_agg(i.resource_key, i.quantity)
       FROM public.inventories i
       JOIN public.resources r ON r.key = i.resource_key
       WHERE i.player_id = p_player_id
         AND r.kind <> 'terrain'
         AND i.quantity > 0),
      '{}'::json
    )
  );
END;
$$;


--
-- Name: get_trade_partner_view(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_trade_partner_view() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_unlocked boolean;
  v_arr jsonb := '[]'::jsonb;
  t record;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  v_unlocked := public.is_trade_unlocked(v_uid);
  IF NOT v_unlocked THEN
    RETURN json_build_object('unlocked', false, 'traders', '[]'::json);
  END IF;

  FOR t IN
    SELECT tr.key, tr.name, tr.specialty_template,
           tr.visit_interval_minutes, tr.visit_capacity,
           public.city_reputation(tr.key) AS city_rep,
           public.city_rep_tier(tr.key) AS city_tier,
           COALESCE((SELECT reputation FROM public.trader_relationships
                     WHERE player_id = v_uid AND trader_key = tr.key), 0) AS your_rep
    FROM public.traders tr
    WHERE tr.is_active
    ORDER BY tr.name
  LOOP
    v_arr := v_arr || jsonb_build_object(
      'key', t.key,
      'name', t.name,
      'specialty_template', t.specialty_template,
      'visit_interval_minutes', t.visit_interval_minutes,
      'visit_capacity', t.visit_capacity,
      'city_rep', t.city_rep,
      'city_tier', t.city_tier,
      'your_rep', t.your_rep
    );
  END LOOP;
  RETURN json_build_object('unlocked', true, 'traders', v_arr);
END;
$$;


--
-- Name: get_trade_stats(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_trade_stats(p_period text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_since timestamptz;
  v_imports jsonb := '[]'::jsonb;
  v_exports jsonb := '[]'::jsonb;
  v_partners jsonb := '[]'::jsonb;
  v_total_in integer := 0;
  v_total_out integer := 0;
  r record;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  v_since := CASE p_period
    WHEN 'today' THEN date_trunc('day', now())
    WHEN 'week'  THEN now() - interval '7 days'
    ELSE timestamp 'epoch'
  END;

  -- Imports: BUY transactions (player paid).
  FOR r IN
    SELECT resource_key, SUM(quantity) AS qty, SUM(total_price) AS spent
    FROM public.trade_transactions
    WHERE player_id = v_uid AND transaction_type = 'buy' AND created_at >= v_since
    GROUP BY resource_key
    ORDER BY spent DESC
  LOOP
    v_imports := v_imports || jsonb_build_object(
      'resource_key', r.resource_key, 'qty', r.qty, 'spent', r.spent
    );
    v_total_out := v_total_out + COALESCE(r.spent, 0)::int;
  END LOOP;

  -- Exports: SELL transactions (player earned).
  FOR r IN
    SELECT resource_key, SUM(quantity) AS qty, SUM(total_price) AS earned
    FROM public.trade_transactions
    WHERE player_id = v_uid AND transaction_type = 'sell' AND created_at >= v_since
    GROUP BY resource_key
    ORDER BY earned DESC
  LOOP
    v_exports := v_exports || jsonb_build_object(
      'resource_key', r.resource_key, 'qty', r.qty, 'earned', r.earned
    );
    v_total_in := v_total_in + COALESCE(r.earned, 0)::int;
  END LOOP;

  -- Partners: rolled by trader_key. Total volume = qty across both directions.
  FOR r IN
    SELECT trader_key, SUM(quantity) AS volume,
           SUM(CASE WHEN transaction_type = 'sell' THEN total_price ELSE 0 END) AS earned,
           SUM(CASE WHEN transaction_type = 'buy'  THEN total_price ELSE 0 END) AS spent
    FROM public.trade_transactions
    WHERE player_id = v_uid AND created_at >= v_since
    GROUP BY trader_key
    ORDER BY volume DESC
    LIMIT 8
  LOOP
    v_partners := v_partners || jsonb_build_object(
      'trader_key', r.trader_key, 'volume', r.volume,
      'earned', r.earned, 'spent', r.spent
    );
  END LOOP;

  RETURN json_build_object(
    'period', p_period,
    'since', v_since,
    'imports', v_imports,
    'exports', v_exports,
    'partners', v_partners,
    'total_in', v_total_in,
    'total_out', v_total_out,
    'net', v_total_in - v_total_out
  );
END;
$$;


--
-- Name: handle_building_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_building_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_bt record;
BEGIN
  IF TG_OP = 'DELETE' THEN
    SELECT * INTO v_bt FROM public.building_types WHERE key = OLD.building_type_key;
    IF v_bt.category = 'road' THEN
      PERFORM public.recompute_extractor_paths(OLD.player_id);
    END IF;
    -- Extractor demolition releases its claim automatically via
    -- ON DELETE SET NULL on map_tiles.claimed_by_building_id.
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: has_road_access(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_road_access(p_x integer, p_y integer) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.buildings b
    JOIN public.building_types bt ON bt.key = b.building_type_key
    WHERE bt.category = 'road' AND b.status = 'active'
      AND ((b.x = p_x - 1 AND b.y = p_y) OR (b.x = p_x + 1 AND b.y = p_y)
           OR (b.x = p_x AND b.y = p_y - 1) OR (b.x = p_x AND b.y = p_y + 1))
  );
$$;


--
-- Name: has_road_access(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_road_access(p_player_id uuid, p_x integer, p_y integer) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.buildings b
    JOIN public.building_types bt ON bt.key = b.building_type_key
    WHERE bt.category = 'road' AND b.status = 'active'
      AND b.player_id = p_player_id
      AND ((b.x = p_x - 1 AND b.y = p_y) OR (b.x = p_x + 1 AND b.y = p_y)
           OR (b.x = p_x AND b.y = p_y - 1) OR (b.x = p_x AND b.y = p_y + 1))
  );
$$;


--
-- Name: has_well_access(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_well_access(p_player_id uuid, p_x integer, p_y integer) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.buildings b
    JOIN public.building_types bt ON bt.key = b.building_type_key
    WHERE bt.key = 'well' AND b.status = 'active'
      AND b.player_id = p_player_id
      AND ABS(b.x - p_x) + ABS(b.y - p_y) <= 4
  );
$$;


--
-- Name: is_trade_unlocked(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_trade_unlocked(p_player_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_has_extractor boolean;
  v_has_food_extractor boolean;
  v_has_tier1 boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM public.buildings b
    JOIN public.building_types bt ON bt.key = b.building_type_key
    WHERE b.player_id = p_player_id AND b.status = 'active'
      AND bt.category = 'extractor'
  ) INTO v_has_extractor;

  SELECT EXISTS (
    SELECT 1 FROM public.buildings b
    JOIN public.building_types bt ON bt.key = b.building_type_key
    WHERE b.player_id = p_player_id AND b.status = 'active'
      AND bt.category = 'food_extractor'
  ) INTO v_has_food_extractor;

  SELECT EXISTS (
    SELECT 1 FROM public.buildings b
    JOIN public.building_types bt ON bt.key = b.building_type_key
    WHERE b.player_id = p_player_id AND b.status = 'active'
      AND bt.category = 'housing' AND b.housing_tier >= 1
  ) INTO v_has_tier1;

  RETURN v_has_extractor AND v_has_food_extractor AND v_has_tier1;
END;
$$;


--
-- Name: next_starter_row(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_starter_row() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_row integer;
  v_max_row integer;
BEGIN
  SELECT max(pp.reserved_row) INTO v_max_row
  FROM public.player_profiles pp
  WHERE pp.reserved_row IS NOT NULL;
  v_row := COALESCE(v_max_row + 1, 0);
  -- Skip rows whose starter chunk (0, row) is already claimed by another
  -- player's expansion. Walk forward until we find a free starter slot.
  WHILE EXISTS (
    SELECT 1 FROM public.district_chunks WHERE chunk_x = 0 AND chunk_y = v_row
  ) LOOP
    v_row := v_row + 1;
  END LOOP;
  RETURN v_row;
END;
$$;


--
-- Name: place_building(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.place_building(p_tile_id uuid, p_building_type_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_bt record;
  v_tile record;
  v_player record;
  v_building_id uuid;
  v_worker_supply integer;
  v_workers_needed integer;
  v_road_connected boolean;
  v_path record;
  v_w int;
  v_h int;
  v_dx int;
  v_dy int;
  v_check_tile record;
  v_footprint_tile_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  SELECT NULL::integer AS target_x, NULL::integer AS target_y, NULL::integer AS path_length
  INTO v_path;
  SELECT * INTO v_bt FROM public.building_types WHERE key = p_building_type_key AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown building type'; END IF;
  SELECT * INTO v_player FROM public.player_profiles WHERE id = v_uid;
  IF NOT FOUND THEN RAISE EXCEPTION 'Player not found'; END IF;
  IF v_bt.industry_key <> 'common' AND v_bt.industry_key <> v_player.industry_key THEN
    RAISE EXCEPTION 'You can only place buildings for your chosen industry';
  END IF;
  IF v_bt.unlocks_at_housing_tier IS NOT NULL
     AND v_player.highest_housing_tier_ever < v_bt.unlocks_at_housing_tier THEN
    RAISE EXCEPTION 'Locked: %', v_bt.name
      USING HINT = 'Reach housing tier ' || v_bt.unlocks_at_housing_tier || ' first';
  END IF;
  IF v_player.money < v_bt.build_cost THEN
    RAISE EXCEPTION 'Not enough money (need %, have %)', v_bt.build_cost, v_player.money;
  END IF;
  SELECT * INTO v_tile FROM public.map_tiles WHERE id = p_tile_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Tile not found'; END IF;

  v_w := COALESCE(v_bt.footprint_w, 1);
  v_h := COALESCE(v_bt.footprint_h, 1);

  FOR v_dx IN 0..(v_w - 1) LOOP
    FOR v_dy IN 0..(v_h - 1) LOOP
      SELECT * INTO v_check_tile FROM public.map_tiles
        WHERE x = v_tile.x + v_dx AND y = v_tile.y + v_dy
        FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Footprint extends off the map at (%, %)', v_tile.x + v_dx, v_tile.y + v_dy;
      END IF;
      IF v_check_tile.owner_player_id IS NULL THEN
        RAISE EXCEPTION 'Cannot build on wilderness — expand your district first';
      END IF;
      IF v_check_tile.owner_player_id <> v_uid THEN
        RAISE EXCEPTION 'Cannot build on another player''s district';
      END IF;
      IF NOT v_check_tile.buildable THEN
        RAISE EXCEPTION 'Tile (%, %) is not buildable', v_check_tile.x, v_check_tile.y;
      END IF;
      IF v_check_tile.occupied_building_id IS NOT NULL THEN
        RAISE EXCEPTION 'Tile (%, %) is already occupied', v_check_tile.x, v_check_tile.y;
      END IF;
      v_footprint_tile_ids := v_footprint_tile_ids || v_check_tile.id;
    END LOOP;
  END LOOP;

  IF v_bt.category = 'road' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.buildings b2
      JOIN public.building_types bt2 ON bt2.key = b2.building_type_key
      WHERE bt2.category = 'road' AND b2.status = 'active' AND b2.player_id = v_uid
        AND ((b2.x = v_tile.x - 1 AND b2.y = v_tile.y)
             OR (b2.x = v_tile.x + 1 AND b2.y = v_tile.y)
             OR (b2.x = v_tile.x AND b2.y = v_tile.y - 1)
             OR (b2.x = v_tile.x AND b2.y = v_tile.y + 1))
    ) INTO v_road_connected;
    IF NOT v_road_connected THEN
      RAISE EXCEPTION 'Roads must connect to another of your roads';
    END IF;
  END IF;

  IF v_bt.category = 'housing' THEN
    INSERT INTO public.buildings (player_id, building_type_key, tile_id, x, y, housing_tier)
    VALUES (v_uid, p_building_type_key, p_tile_id, v_tile.x, v_tile.y, 0)
    RETURNING id INTO v_building_id;
  ELSE
    INSERT INTO public.buildings (player_id, building_type_key, tile_id, x, y)
    VALUES (v_uid, p_building_type_key, p_tile_id, v_tile.x, v_tile.y)
    RETURNING id INTO v_building_id;
  END IF;

  UPDATE public.map_tiles SET occupied_building_id = v_building_id
    WHERE id = ANY(v_footprint_tile_ids);

  IF v_bt.category = 'extractor' THEN
    SELECT * INTO v_path FROM public.find_nearest_unclaimed_resource(v_uid, v_tile.x, v_tile.y);
    IF v_path.path_length IS NOT NULL THEN
      UPDATE public.buildings
        SET target_x = v_path.target_x, target_y = v_path.target_y, path_length = v_path.path_length
      WHERE id = v_building_id;
      UPDATE public.map_tiles SET claimed_by_building_id = v_building_id
        WHERE x = v_path.target_x AND y = v_path.target_y;
    END IF;
  END IF;

  IF v_bt.category = 'road' THEN
    PERFORM public.recompute_extractor_paths(v_uid);
  END IF;

  v_worker_supply := 5 + public._pp_housing_supply(v_uid);
  v_workers_needed := public._pp_workers_needed(v_uid);

  UPDATE public.player_profiles
  SET money = money - v_bt.build_cost,
      worker_capacity = v_worker_supply,
      workers_used = LEAST(v_worker_supply, v_workers_needed)
  WHERE id = v_uid RETURNING * INTO v_player;

  -- Log the spend.
  IF v_bt.build_cost > 0 THEN
    INSERT INTO public.cash_transactions (player_id, source, amount, context)
    VALUES (v_uid, 'build_cost', -v_bt.build_cost,
            jsonb_build_object('building_type_key', p_building_type_key, 'building_id', v_building_id));
  END IF;

  RETURN json_build_object(
    'building_id', v_building_id,
    'money', v_player.money,
    'workers_used', v_player.workers_used,
    'worker_capacity', v_player.worker_capacity,
    'workers_needed', v_workers_needed,
    'labor_shortage', v_workers_needed > v_worker_supply,
    'extractor_target', CASE WHEN v_path.path_length IS NOT NULL
      THEN json_build_object('x', v_path.target_x, 'y', v_path.target_y, 'path_length', v_path.path_length)
      ELSE NULL END
  );
END;
$$;


--
-- Name: place_pre_road(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.place_pre_road(p_player_id uuid, p_x integer, p_y integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_tile record;
  v_bid uuid;
BEGIN
  SELECT * INTO v_tile FROM public.map_tiles
  WHERE x = p_x AND y = p_y AND owner_player_id = p_player_id;
  IF NOT FOUND THEN RETURN; END IF;
  IF v_tile.occupied_building_id IS NOT NULL THEN RETURN; END IF;
  -- Clear any resource cluster that landed on the path before inserting
  -- the road (the reject_build_on_resource trigger would otherwise block).
  IF v_tile.resource_node_key IS NOT NULL THEN
    UPDATE public.map_tiles SET resource_node_key = NULL WHERE id = v_tile.id;
  END IF;
  INSERT INTO public.buildings (player_id, building_type_key, tile_id, x, y)
  VALUES (p_player_id, 'road', v_tile.id, p_x, p_y)
  RETURNING id INTO v_bid;
  UPDATE public.map_tiles SET occupied_building_id = v_bid WHERE id = v_tile.id;
END;
$$;


--
-- Name: preview_extractor_target(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_extractor_target(p_x integer, p_y integer) RETURNS json
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_path record;
BEGIN
  IF v_uid IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO v_path FROM public.find_nearest_unclaimed_resource(v_uid, p_x, p_y);
  IF v_path.path_length IS NULL THEN
    RETURN json_build_object('target', NULL);
  END IF;
  RETURN json_build_object(
    'target', json_build_object(
      'x', v_path.target_x, 'y', v_path.target_y,
      'path_length', v_path.path_length
    )
  );
END;
$$;


--
-- Name: process_production(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_production() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_base constant integer := 5;
  v_tavern_bonus integer;
  v_supply integer;
  v_staffing record;
  v_total_produced numeric := 0;
  v_total_money integer := 0;
  v_total_upkeep integer := 0;
  v_food_drained numeric := 0;
  v_evolution_events json[];
  v_operating_services uuid[];
  v_partial numeric;
  v_population numeric;
  v_crime numeric;
BEGIN
  v_tavern_bonus := public._pp_tavern_bonus(v_uid);

  v_population := public._pp_update_population(v_uid);
  v_supply := FLOOR(v_population)::integer + v_tavern_bonus;

  SELECT staffed_ids, workers_needed, unstaffed_count
    INTO v_staffing
    FROM public._pp_staff_buildings(v_uid, v_supply);

  v_partial := public._pp_run_extractors(v_uid, v_staffing.staffed_ids);
  v_total_produced := v_total_produced + v_partial;
  v_partial := public._pp_run_food_extractors(v_uid, v_staffing.staffed_ids);
  v_total_produced := v_total_produced + v_partial;
  PERFORM public._pp_bump_boosters(v_uid, v_staffing.staffed_ids);
  v_partial := public._pp_run_processors(v_uid, v_staffing.staffed_ids);
  v_total_produced := v_total_produced + v_partial;

  v_operating_services := public._pp_run_services(v_uid, v_staffing.staffed_ids);
  v_total_money := public._pp_run_tax(v_uid, v_staffing.staffed_ids);
  v_total_upkeep := public._pp_run_upkeep(v_uid, v_staffing.staffed_ids);

  v_food_drained := public._pp_drain_housing_food(v_uid);

  v_evolution_events := public._pp_evolve_housing(v_uid, v_operating_services);

  v_crime := public._pp_update_crime(v_uid);

  v_supply := FLOOR(v_population)::integer + v_tavern_bonus;
  UPDATE public.player_profiles
  SET worker_capacity = v_supply,
      workers_used = LEAST(v_supply, v_staffing.workers_needed)
  WHERE id = v_uid;

  RETURN json_build_object(
    'total_produced', v_total_produced,
    'total_money_collected', v_total_money,
    'total_upkeep_paid', v_total_upkeep,
    'food_drained', v_food_drained,
    'evolution_events', array_to_json(v_evolution_events),
    'worker_supply', v_supply,
    'workers_needed', v_staffing.workers_needed,
    'unstaffed_count', v_staffing.unstaffed_count,
    'population', v_population,
    'happiness', (SELECT happiness FROM public.player_profiles WHERE id = v_uid),
    'crime', v_crime
  );
END;
$$;


--
-- Name: propose_trade(uuid, integer, jsonb, integer, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propose_trade(p_to_player_id uuid, p_give_money integer, p_give_resources jsonb, p_receive_money integer, p_receive_resources jsonb, p_message text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_offer_id uuid;
  v_resource_key text;
  v_qty numeric;
  v_target_exists boolean;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_to_player_id IS NULL OR p_to_player_id = v_uid THEN
    RAISE EXCEPTION 'Invalid trade target';
  END IF;
  IF p_give_money < 0 OR p_receive_money < 0 THEN
    RAISE EXCEPTION 'Money amounts must be non-negative';
  END IF;
  IF p_give_resources IS NULL THEN p_give_resources := '{}'::jsonb; END IF;
  IF p_receive_resources IS NULL THEN p_receive_resources := '{}'::jsonb; END IF;

  -- Reject empty offers.
  IF p_give_money = 0 AND p_receive_money = 0
     AND p_give_resources = '{}'::jsonb AND p_receive_resources = '{}'::jsonb THEN
    RAISE EXCEPTION 'Trade offer cannot be empty';
  END IF;

  -- Confirm target player exists.
  SELECT EXISTS(SELECT 1 FROM public.player_profiles WHERE id = p_to_player_id)
    INTO v_target_exists;
  IF NOT v_target_exists THEN
    RAISE EXCEPTION 'Target player not found';
  END IF;

  -- Validate every resource_key actually exists. Better to fail at
  -- propose time than silently create an unaccepteable offer.
  FOR v_resource_key, v_qty IN
    SELECT key, value::text::numeric FROM jsonb_each_text(p_give_resources)
  LOOP
    IF v_qty <= 0 THEN
      RAISE EXCEPTION 'give_resources qty for % must be positive', v_resource_key;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.resources WHERE key = v_resource_key) THEN
      RAISE EXCEPTION 'Unknown resource: %', v_resource_key;
    END IF;
  END LOOP;
  FOR v_resource_key, v_qty IN
    SELECT key, value::text::numeric FROM jsonb_each_text(p_receive_resources)
  LOOP
    IF v_qty <= 0 THEN
      RAISE EXCEPTION 'receive_resources qty for % must be positive', v_resource_key;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.resources WHERE key = v_resource_key) THEN
      RAISE EXCEPTION 'Unknown resource: %', v_resource_key;
    END IF;
  END LOOP;

  INSERT INTO public.player_trade_offers (
    from_player_id, to_player_id,
    give_money, give_resources,
    receive_money, receive_resources,
    message
  ) VALUES (
    v_uid, p_to_player_id,
    p_give_money, p_give_resources,
    p_receive_money, p_receive_resources,
    p_message
  ) RETURNING id INTO v_offer_id;

  RETURN v_offer_id;
END;
$$;


--
-- Name: recompute_extractor_paths(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_extractor_paths(p_player_id uuid) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_extractor record;
  v_path record;
  v_verify integer;
  v_recomputed integer := 0;
  v_idle integer := 0;
BEGIN
  FOR v_extractor IN
    SELECT b.id, b.x, b.y, b.target_x, b.target_y
    FROM public.buildings b
    JOIN public.building_types bt ON bt.key = b.building_type_key
    WHERE b.player_id = p_player_id
      AND bt.category = 'extractor'
      AND b.status = 'active'
  LOOP
    IF v_extractor.target_x IS NOT NULL THEN
      -- Verify current path
      v_verify := public.verify_extractor_path(
        p_player_id, v_extractor.x, v_extractor.y,
        v_extractor.target_x, v_extractor.target_y
      );
      IF v_verify IS NOT NULL THEN
        -- Path still valid; refresh path_length in case roads were optimized
        UPDATE public.buildings SET path_length = v_verify WHERE id = v_extractor.id;
        v_recomputed := v_recomputed + 1;
        CONTINUE;
      END IF;
      -- Path broken — release claim
      UPDATE public.map_tiles
      SET claimed_by_building_id = NULL
      WHERE claimed_by_building_id = v_extractor.id;
      UPDATE public.buildings
      SET target_x = NULL, target_y = NULL, path_length = NULL
      WHERE id = v_extractor.id;
    END IF;

    -- Try to find a new target
    SELECT * INTO v_path
    FROM public.find_nearest_unclaimed_resource(
      p_player_id, v_extractor.x, v_extractor.y
    );
    IF v_path IS NOT NULL AND v_path.path_length IS NOT NULL THEN
      UPDATE public.buildings
      SET target_x = v_path.target_x,
          target_y = v_path.target_y,
          path_length = v_path.path_length
      WHERE id = v_extractor.id;
      UPDATE public.map_tiles
      SET claimed_by_building_id = v_extractor.id
      WHERE x = v_path.target_x AND y = v_path.target_y;
      v_recomputed := v_recomputed + 1;
    ELSE
      v_idle := v_idle + 1;
    END IF;
  END LOOP;

  RETURN json_build_object('recomputed', v_recomputed, 'idle', v_idle);
END;
$$;


--
-- Name: reject_build_on_resource(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_build_on_resource() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_resource text;
  v_required text;
BEGIN
  SELECT mt.resource_node_key INTO v_resource
  FROM public.map_tiles mt WHERE mt.id = NEW.tile_id;
  SELECT placement_resource_node_key INTO v_required
  FROM public.building_types WHERE key = NEW.building_type_key;
  IF v_required IS NOT NULL THEN
    IF v_resource IS DISTINCT FROM v_required THEN
      RAISE EXCEPTION '% needs to be placed on a % tile', NEW.building_type_key, v_required;
    END IF;
    RETURN NEW;
  END IF;
  IF v_resource IS NOT NULL THEN
    RAISE EXCEPTION 'Cannot build on a % tile - clear it first', v_resource;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: reject_trade(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_trade(p_offer_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_offer record;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT * INTO v_offer FROM public.player_trade_offers
    WHERE id = p_offer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Offer not found'; END IF;
  IF v_offer.to_player_id <> v_uid THEN
    RAISE EXCEPTION 'Only the recipient can reject this offer';
  END IF;
  IF v_offer.status <> 'pending' THEN
    RAISE EXCEPTION 'Offer is %', v_offer.status;
  END IF;
  UPDATE public.player_trade_offers
    SET status = 'rejected', resolved_at = now()
    WHERE id = p_offer_id;
END;
$$;


--
-- Name: reset_player(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_player(p_player_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  DELETE FROM public.buildings WHERE player_id = p_player_id;
  DELETE FROM public.map_tiles WHERE owner_player_id = p_player_id;
  DELETE FROM public.district_chunks WHERE owner_player_id = p_player_id;
  DELETE FROM public.inventories WHERE player_id = p_player_id;
  DELETE FROM public.player_profiles WHERE id = p_player_id;
END;
$$;


--
-- Name: resolve_trader_visit(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_trader_visit(p_trader_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_trader record;
  v_last_visit timestamptz;
  v_interval interval;
  v_player_money integer;
  v_visit_at timestamptz;
  v_next_visit_at timestamptz;
  v_iterations integer := 0;
  v_max_iterations constant integer := 50;
  v_total_earned integer := 0;
  v_total_spent integer := 0;
  v_summary jsonb := '[]'::jsonb;
  v_visit_summary jsonb;
  v_visits_resolved integer := 0;
  v_first_visit_id uuid;
  v_last_resolved_id uuid;
  v_sell record;
  v_buy record;
BEGIN
  PERFORM public.process_production();

  SELECT * INTO v_trader FROM public.traders WHERE key = p_trader_key AND is_active;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Trader not found: %', p_trader_key;
  END IF;

  v_interval := (v_trader.visit_interval_minutes::text || ' minutes')::interval;

  SELECT visited_at INTO v_last_visit
  FROM public.trader_visits
  WHERE player_id = v_uid AND trader_key = p_trader_key
  ORDER BY visited_at DESC
  LIMIT 1;

  IF v_last_visit IS NULL THEN
    SELECT created_at INTO v_last_visit FROM public.player_profiles WHERE id = v_uid;
  END IF;

  v_next_visit_at := v_last_visit + v_interval;
  IF now() < v_next_visit_at THEN
    RETURN json_build_object(
      'visit_resolved', false,
      'next_visit_at', v_next_visit_at,
      'trader_key', p_trader_key,
      'reason', 'not_due'
    );
  END IF;

  SELECT money INTO v_player_money FROM public.player_profiles WHERE id = v_uid;

  -- Catch up every missed visit, capped at v_max_iterations.
  WHILE v_next_visit_at <= now() AND v_iterations < v_max_iterations LOOP
    v_iterations := v_iterations + 1;
    v_visit_at := v_next_visit_at;

    SELECT * INTO v_sell
      FROM public._rtv_sell_phase(v_uid, p_trader_key, v_trader.visit_capacity);
    IF v_sell.earned > 0 THEN
      UPDATE public.player_profiles SET money = money + v_sell.earned WHERE id = v_uid;
      v_player_money := v_player_money + v_sell.earned;
    END IF;

    SELECT * INTO v_buy
      FROM public._rtv_buy_phase(
        v_uid,
        p_trader_key,
        v_trader.visit_capacity - v_sell.capacity_used,
        v_player_money
      );
    IF v_buy.spent > 0 THEN
      UPDATE public.player_profiles SET money = money - v_buy.spent WHERE id = v_uid;
      v_player_money := v_buy.money_out;
    END IF;

    v_visit_summary := v_sell.summary || v_buy.summary;

    INSERT INTO public.trader_visits
      (trader_key, player_id, capacity_total, capacity_used, summary, visited_at)
    VALUES
      (p_trader_key, v_uid, v_trader.visit_capacity,
       v_sell.capacity_used + v_buy.capacity_used,
       v_visit_summary, v_visit_at)
    RETURNING id INTO v_last_resolved_id;

    IF v_first_visit_id IS NULL THEN v_first_visit_id := v_last_resolved_id; END IF;

    v_total_earned := v_total_earned + v_sell.earned;
    v_total_spent := v_total_spent + v_buy.spent;
    v_summary := v_summary || v_visit_summary;
    v_visits_resolved := v_visits_resolved + 1;
    v_next_visit_at := v_visit_at + v_interval;
  END LOOP;

  RETURN json_build_object(
    'visit_resolved', true,
    'trader_key', p_trader_key,
    'visit_id', v_last_resolved_id,
    'visits_resolved', v_visits_resolved,
    'capacity_total', v_trader.visit_capacity * v_visits_resolved,
    'capacity_used', LEAST(
      v_trader.visit_capacity * v_visits_resolved,
      jsonb_array_length(v_summary)
    ),
    'total_earned', v_total_earned,
    'total_spent', v_total_spent,
    'summary', v_summary,
    'next_visit_at', v_next_visit_at,
    'money', v_player_money,
    'inventory', COALESCE(
      (SELECT json_object_agg(resource_key, quantity)
       FROM public.inventories WHERE player_id = v_uid),
      '{}'::json
    )
  );
END;
$$;


--
-- Name: roll_trader_missions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.roll_trader_missions() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  r record;
  v_last timestamptz;
  v_target integer;
  v_resource text;
  v_pop integer;
  v_now timestamptz := now();
  v_rolled integer := 0;
  v_resources_for_template text[];
BEGIN
  FOR r IN
    SELECT t.key, t.mission_cooldown_minutes, t.base_request_qty,
           t.soft_deadline_minutes, t.specialty_template
    FROM public.traders t
    WHERE t.is_active
  LOOP
    -- Skip if there's already an open mission for this trader.
    IF EXISTS (SELECT 1 FROM public.trader_missions
               WHERE trader_key = r.key AND status = 'open') THEN
      CONTINUE;
    END IF;

    -- Check cooldown vs. last mission (or trader creation).
    SELECT MAX(resolved_at) INTO v_last
    FROM public.trader_missions
    WHERE trader_key = r.key AND status <> 'open';
    IF v_last IS NULL THEN v_last := v_now - interval '1 day'; END IF;
    IF v_last + (r.mission_cooldown_minutes || ' minutes')::interval > v_now THEN
      CONTINUE;
    END IF;

    -- Resource pool by specialty template. Trader's current rep tier
    -- decides how many goods are available; for v1 we pick uniformly
    -- from the buyable side of the trader's template.
    v_resources_for_template := CASE r.specialty_template
      WHEN 'resource_buyer' THEN ARRAY['lumber','stone','clay','iron','planks','brick','pottery']
      WHEN 'food_buyer'     THEN ARRAY['grain','flour','bread','berries','fish','vegetables','wine','smoked_fish','preserves']
      WHEN 'luxury_buyer'   THEN ARRAY['statuary','cabinets','monuments','mosaics','machinery','spirits','caviar','spices','ale']
      WHEN 'specialist'     THEN ARRAY['lumber','planks','statuary','grain','flour','bread']
      ELSE ARRAY['lumber','grain','stone','flour','clay','fish']
    END;

    -- Filter to resources that actually exist in the catalog.
    SELECT v_resources_for_template[1 + floor(random() * array_length(v_resources_for_template, 1))::int]
      INTO v_resource;
    IF NOT EXISTS (SELECT 1 FROM public.resources WHERE key = v_resource) THEN
      CONTINUE;
    END IF;

    -- Scale target by city population (sum of districts' weights).
    SELECT COALESCE(SUM(public.district_weight(pp.id)), 1) INTO v_pop
    FROM public.player_profiles pp;
    v_target := GREATEST(1, ROUND(r.base_request_qty * (1.0 + 0.10 * ln(1 + v_pop))))::int;

    INSERT INTO public.trader_missions
      (trader_key, kind, resource_key, target_qty, current_qty,
       soft_deadline, expires_at, status, created_at)
    VALUES
      (r.key, 'deliver_resource', v_resource, v_target, 0,
       v_now + (r.soft_deadline_minutes || ' minutes')::interval,
       v_now + ((r.soft_deadline_minutes + 360) || ' minutes')::interval,
       'open', v_now);
    v_rolled := v_rolled + 1;
  END LOOP;
  RETURN v_rolled;
END;
$$;


--
-- Name: save_trade_policy(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_trade_policy(p_resource_key text, p_mode text, p_reserve_target integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF p_mode NOT IN ('keep', 'sell_surplus', 'buy_to_reserve') THEN
    RAISE EXCEPTION 'Invalid trade mode: %', p_mode;
  END IF;
  IF p_reserve_target < 0 THEN
    RAISE EXCEPTION 'Reserve target cannot be negative';
  END IF;

  INSERT INTO public.trade_policies (player_id, resource_key, mode, reserve_target)
  VALUES (v_uid, p_resource_key, p_mode, p_reserve_target)
  ON CONFLICT (player_id, resource_key)
  DO UPDATE SET mode = p_mode, reserve_target = p_reserve_target, updated_at = now();

  RETURN json_build_object('ok', true, 'resource_key', p_resource_key, 'mode', p_mode, 'reserve_target', p_reserve_target);
END;
$$;


--
-- Name: seed_district_tiles(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_district_tiles(p_district_id uuid, p_specialization_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_district record;
  v_world_id uuid;
  v_spec_resource text;
  v_secondary_resource text;
  v_tertiary_resource text;
  v_all_raw text[] := array['timber', 'stone', 'grain', 'clay', 'iron_ore'];
  v_others text[];
  v_dx int;
  v_dy int;
  v_abs_x int;
  v_abs_y int;
  v_tile_index int;
  v_resource text;
  v_terrain text;
  v_seed int;
begin
  -- Load district
  select * into v_district from public.districts where id = p_district_id;
  if v_district is null then
    raise exception 'District not found';
  end if;
  v_world_id := v_district.world_id;

  -- Map specialization_key to resource_key (iron_ore uses iron_ore)
  v_spec_resource := p_specialization_key;

  -- Pick secondary and tertiary resources (deterministic by district position)
  v_others := array[]::text[];
  for i in 1..array_length(v_all_raw, 1) loop
    if v_all_raw[i] != v_spec_resource then
      v_others := v_others || v_all_raw[i];
    end if;
  end loop;
  -- Use origin coords as a simple seed for selection
  v_seed := (v_district.origin_x * 7 + v_district.origin_y * 13) % array_length(v_others, 1);
  v_secondary_resource := v_others[(v_seed % array_length(v_others, 1)) + 1];
  v_tertiary_resource := v_others[((v_seed + 1) % array_length(v_others, 1)) + 1];

  -- Generate 8x8 = 64 tiles
  for v_dy in 0..v_district.height - 1 loop
    for v_dx in 0..v_district.width - 1 loop
      v_abs_x := v_district.origin_x + v_dx;
      v_abs_y := v_district.origin_y + v_dy;
      v_tile_index := v_dy * v_district.width + v_dx;

      -- Resource placement pattern (deterministic, using tile index):
      -- Indices 10,11,18,19,26,34 → primary resource (6 tiles)
      -- Indices 5,44            → secondary resource (2 tiles)
      -- Index  37               → tertiary resource (1 tile)
      v_resource := null;
      if v_tile_index in (10, 11, 18, 19, 26, 34) then
        v_resource := v_spec_resource;
      elsif v_tile_index in (5, 44) then
        v_resource := v_secondary_resource;
      elsif v_tile_index = 37 then
        v_resource := v_tertiary_resource;
      end if;

      -- Terrain: resource tiles get matching terrain hint, others get grass
      if v_resource is not null then
        v_terrain := v_resource;
      else
        v_terrain := 'grass';
      end if;

      insert into public.tiles (world_id, district_id, x, y, terrain_key, resource_key, is_revealed, is_buildable, owner_player_id)
      values (v_world_id, p_district_id, v_abs_x, v_abs_y, v_terrain, v_resource, true, true, v_district.owner_player_id)
      on conflict (world_id, x, y) do nothing;
    end loop;
  end loop;
end;
$$;


--
-- Name: sell_to_trader(text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sell_to_trader(p_trader_key text, p_resource_key text, p_quantity numeric) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_price integer;
  v_total integer;
  v_available numeric;
  v_new_money integer;
BEGIN
  -- Catch up production first
  PERFORM public.process_production();

  SELECT buy_price INTO v_price
  FROM public.trader_prices
  WHERE trader_key = p_trader_key AND resource_key = p_resource_key AND is_active;
  IF NOT FOUND OR v_price IS NULL THEN RAISE EXCEPTION 'Trader does not buy this resource'; END IF;

  SELECT COALESCE(quantity, 0) INTO v_available
  FROM public.inventories
  WHERE player_id = v_uid AND resource_key = p_resource_key;
  IF v_available < p_quantity THEN
    RAISE EXCEPTION 'Not enough % (have %, need %)', p_resource_key, v_available, p_quantity;
  END IF;

  v_total := v_price * p_quantity;

  UPDATE public.inventories
  SET quantity = quantity - p_quantity, updated_at = now()
  WHERE player_id = v_uid AND resource_key = p_resource_key;

  UPDATE public.player_profiles
  SET money = money + v_total
  WHERE id = v_uid
  RETURNING money INTO v_new_money;

  INSERT INTO public.trade_transactions (player_id, trader_key, resource_key, quantity, unit_price, total_price)
  VALUES (v_uid, p_trader_key, p_resource_key, p_quantity, v_price, v_total);

  RETURN json_build_object(
    'total_price', v_total,
    'money', v_new_money,
    'inventory', COALESCE(
      (SELECT json_object_agg(resource_key, quantity)
       FROM public.inventories WHERE player_id = v_uid),
      '{}'::json
    )
  );
END;
$$;


--
-- Name: set_building_paused(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_building_paused(p_building_id uuid, p_paused boolean) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_new_status text;
BEGIN
  SELECT player_id INTO v_owner FROM public.buildings WHERE id = p_building_id;
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'Building not found';
  END IF;
  IF v_owner <> v_uid THEN
    RAISE EXCEPTION 'You can only pause your own buildings';
  END IF;
  v_new_status := CASE WHEN p_paused THEN 'paused' ELSE 'active' END;
  UPDATE public.buildings
  SET status = v_new_status,
      -- Reset last_processed_at so we don't credit elapsed-time for
      -- the time it sat paused. Without this, resuming a building
      -- after an hour would dump an hour's worth of production at once.
      last_processed_at = now()
  WHERE id = p_building_id;
  RETURN json_build_object('building_id', p_building_id, 'status', v_new_status);
END;
$$;


--
-- Name: set_building_priority(uuid, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_building_priority(p_building_id uuid, p_priority smallint) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_owner uuid;
BEGIN
  IF p_priority NOT IN (0, 1, 2) THEN
    RAISE EXCEPTION 'Priority must be 0 (low), 1 (normal), or 2 (high)';
  END IF;
  SELECT player_id INTO v_owner FROM public.buildings WHERE id = p_building_id;
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'Building not found';
  END IF;
  IF v_owner <> v_uid THEN
    RAISE EXCEPTION 'You can only change priority on your own buildings';
  END IF;
  UPDATE public.buildings SET staffing_priority = p_priority WHERE id = p_building_id;
  RETURN json_build_object('building_id', p_building_id, 'priority', p_priority);
END;
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: verify_extractor_path(uuid, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_extractor_path(p_player_id uuid, p_ex integer, p_ey integer, p_tx integer, p_ty integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_state jsonb := '{}'::jsonb;
  v_cur_key text;
  v_cur_dist integer;
  v_cur_x integer;
  v_cur_y integer;
  v_neighbor_x integer;
  v_neighbor_y integer;
  v_neighbor_key text;
  v_neighbor_cost integer;
  v_existing_dist integer;
  v_is_road boolean;
  v_neighbor_walkable boolean;
  v_dx int[] := ARRAY[-1, 1, 0, 0];
  v_dy int[] := ARRAY[0, 0, -1, 1];
  v_i integer;
  v_iters integer := 0;
  v_road_cost constant integer := 1;
  v_offroad_cost constant integer := 3;
BEGIN
  v_state := jsonb_build_object(
    p_ex || ',' || p_ey,
    jsonb_build_object('x', p_ex, 'y', p_ey, 'd', 0, 'v', false)
  );
  WHILE v_iters < 2000 LOOP
    v_iters := v_iters + 1;
    SELECT key, (value->>'x')::int, (value->>'y')::int, (value->>'d')::int
    INTO v_cur_key, v_cur_x, v_cur_y, v_cur_dist
    FROM jsonb_each(v_state)
    WHERE (value->>'v')::boolean = false
    ORDER BY (value->>'d')::int ASC LIMIT 1;
    IF v_cur_key IS NULL THEN RETURN NULL; END IF;
    IF v_cur_x = p_tx AND v_cur_y = p_ty THEN RETURN v_cur_dist; END IF;
    v_state := jsonb_set(v_state, ARRAY[v_cur_key, 'v'], 'true'::jsonb);
    FOR v_i IN 1..4 LOOP
      v_neighbor_x := v_cur_x + v_dx[v_i];
      v_neighbor_y := v_cur_y + v_dy[v_i];
      v_neighbor_key := v_neighbor_x || ',' || v_neighbor_y;
      SELECT EXISTS (
        SELECT 1 FROM public.buildings b
        JOIN public.building_types bt ON bt.key = b.building_type_key
        WHERE b.x = v_neighbor_x AND b.y = v_neighbor_y
          AND bt.category = 'road' AND b.status = 'active'
          AND b.player_id = p_player_id
      ) INTO v_is_road;
      IF v_is_road THEN
        v_neighbor_cost := v_road_cost;
        v_neighbor_walkable := true;
      ELSE
        SELECT EXISTS (
          SELECT 1 FROM public.map_tiles mt
          WHERE mt.x = v_neighbor_x AND mt.y = v_neighbor_y
            AND mt.owner_player_id = p_player_id
            AND (mt.occupied_building_id IS NULL OR (mt.x = p_tx AND mt.y = p_ty))
        ) INTO v_neighbor_walkable;
        v_neighbor_cost := v_offroad_cost;
      END IF;
      IF NOT v_neighbor_walkable THEN CONTINUE; END IF;
      IF v_state ? v_neighbor_key THEN
        IF NOT ((v_state->v_neighbor_key->>'v')::boolean) THEN
          v_existing_dist := (v_state->v_neighbor_key->>'d')::int;
          IF v_cur_dist + v_neighbor_cost < v_existing_dist THEN
            v_state := jsonb_set(v_state, ARRAY[v_neighbor_key, 'd'],
              to_jsonb(v_cur_dist + v_neighbor_cost));
          END IF;
        END IF;
      ELSE
        v_state := v_state || jsonb_build_object(
          v_neighbor_key,
          jsonb_build_object('x', v_neighbor_x, 'y', v_neighbor_y,
            'd', v_cur_dist + v_neighbor_cost, 'v', false)
        );
      END IF;
    END LOOP;
  END LOOP;
  RETURN NULL;
END;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: building_types; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.building_types (
    key text NOT NULL,
    name text NOT NULL,
    tier integer NOT NULL,
    industry_key text NOT NULL,
    category text NOT NULL,
    build_cost integer NOT NULL,
    worker_cost integer DEFAULT 1 NOT NULL,
    input_resource_key text,
    input_rate numeric DEFAULT 0 NOT NULL,
    output_resource_key text,
    output_rate numeric NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    workers_provided integer DEFAULT 0 NOT NULL,
    input_resource_key_2 text,
    input_rate_2 numeric DEFAULT 0 NOT NULL,
    boost_target text,
    boost_multiplier numeric DEFAULT 1.0 NOT NULL,
    boost_range integer DEFAULT 0 NOT NULL,
    placement_resource_node_key text,
    footprint_w smallint DEFAULT 1 NOT NULL,
    footprint_h smallint DEFAULT 1 NOT NULL,
    unlocks_at_housing_tier integer,
    coverage_radius integer DEFAULT 0 NOT NULL,
    upkeep_per_minute integer DEFAULT 0 NOT NULL,
    CONSTRAINT building_types_category_check CHECK ((category = ANY (ARRAY['extractor'::text, 'processor'::text, 'housing'::text, 'road'::text, 'service'::text, 'tax'::text, 'food_extractor'::text, 'booster'::text, 'police'::text]))),
    CONSTRAINT building_types_footprint_h_check CHECK (((footprint_h >= 1) AND (footprint_h <= 4))),
    CONSTRAINT building_types_footprint_w_check CHECK (((footprint_w >= 1) AND (footprint_w <= 4))),
    CONSTRAINT building_types_tier_check CHECK ((tier = ANY (ARRAY[1, 2, 3, 4])))
);


--
-- Name: buildings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.buildings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    player_id uuid NOT NULL,
    building_type_key text NOT NULL,
    tile_id uuid NOT NULL,
    x integer NOT NULL,
    y integer NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    stored_input numeric DEFAULT 0 NOT NULL,
    stored_output numeric DEFAULT 0 NOT NULL,
    last_processed_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    housing_tier integer DEFAULT 1 NOT NULL,
    evolution_eligible_at timestamp with time zone,
    target_x integer,
    target_y integer,
    path_length integer,
    staffing_priority smallint DEFAULT 1 NOT NULL,
    is_staffed boolean DEFAULT false NOT NULL,
    CONSTRAINT buildings_staffing_priority_check CHECK (((staffing_priority >= 0) AND (staffing_priority <= 2))),
    CONSTRAINT buildings_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text])))
);


--
-- Name: cash_transactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cash_transactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    player_id uuid NOT NULL,
    source text NOT NULL,
    amount integer NOT NULL,
    context jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT cash_source_check CHECK ((source = ANY (ARRAY['tax_revenue'::text, 'build_cost'::text, 'expansion_cost'::text, 'starting_grant'::text, 'demolish_refund'::text, 'upkeep'::text])))
);


--
-- Name: counter; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.counter (
    id integer DEFAULT 1 NOT NULL,
    count integer DEFAULT 0 NOT NULL,
    CONSTRAINT counter_id_check CHECK ((id = 1))
);


--
-- Name: district_chunks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.district_chunks (
    chunk_x integer NOT NULL,
    chunk_y integer NOT NULL,
    owner_player_id uuid NOT NULL,
    allocated_at timestamp with time zone DEFAULT now() NOT NULL
);


