);


--
-- Name: player_trade_offers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.player_trade_offers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    from_player_id uuid NOT NULL,
    to_player_id uuid NOT NULL,
    give_money integer DEFAULT 0 NOT NULL,
    give_resources jsonb DEFAULT '{}'::jsonb NOT NULL,
    receive_money integer DEFAULT 0 NOT NULL,
    receive_resources jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    CONSTRAINT trade_offers_distinct_parties CHECK ((from_player_id <> to_player_id)),
    CONSTRAINT trade_offers_money_nonneg CHECK (((give_money >= 0) AND (receive_money >= 0))),
    CONSTRAINT trade_offers_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'rejected'::text, 'cancelled'::text])))
);


