    CONSTRAINT trader_missions_kind_check CHECK ((kind = 'deliver_resource'::text)),
    CONSTRAINT trader_missions_status_check CHECK ((status = ANY (ARRAY['open'::text, 'fulfilled'::text, 'expired'::text]))),
    CONSTRAINT trader_missions_target_pos CHECK ((target_qty > 0))
);


