INSERT INTO public.external_trade_partners (id, world_id, name, description, buy_catalog, sell_catalog, is_active, created_at) VALUES ('9ae3f0fe-f6e0-434a-afff-ecbf11f6e7a2', '46c4e125-d62f-424b-9551-0738afb3a19d', 'River Traders', 'Barge merchants who haul raw goods downstream. They pay fair prices for timber and grain, and carry surplus bread upriver.', '{"clay": {"price": 6, "max_per_trade": 15}, "grain": {"price": 7, "max_per_trade": 20}, "timber": {"price": 8, "max_per_trade": 20}}', '{"bread": {"price": 18, "max_per_trade": 10}, "flour": {"price": 12, "max_per_trade": 10}}', true, '2026-05-01 01:08:23.561725+00');
INSERT INTO public.external_trade_partners (id, world_id, name, description, buy_catalog, sell_catalog, is_active, created_at) VALUES ('93c57077-feb7-49ef-95af-01d311826fab', '46c4e125-d62f-424b-9551-0738afb3a19d', 'Mountain Folk', 'Hardy miners from the northern ranges. They trade in stone, ore, and the finest forged tools.', '{"stone": {"price": 9, "max_per_trade": 20}, "iron_ore": {"price": 10, "max_per_trade": 15}, "cut_stone": {"price": 18, "max_per_trade": 10}}', '{"tools": {"price": 25, "max_per_trade": 8}, "iron_bars": {"price": 16, "max_per_trade": 10}}', true, '2026-05-01 01:08:23.561725+00');
INSERT INTO public.external_trade_partners (id, world_id, name, description, buy_catalog, sell_catalog, is_active, created_at) VALUES ('2e5874e5-334a-440a-8b7e-3a539f3e44c2', '46c4e125-d62f-424b-9551-0738afb3a19d', 'Desert Caravan', 'Exotic merchants crossing the southern wastes. They prize construction goods and offer pottery and fine goods in return.', '{"bricks": {"price": 13, "max_per_trade": 15}, "iron_bars": {"price": 15, "max_per_trade": 10}, "wood_planks": {"price": 14, "max_per_trade": 15}}', '{"pottery": {"price": 22, "max_per_trade": 8}, "fine_goods": {"price": 35, "max_per_trade": 5}}', true, '2026-05-01 01:08:23.561725+00');
